window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["中国气象局"] = {"rengongzhinengqixiangyingyongfuwubanfa":[{"i":1,"n":"第一条","txt":"为了鼓励和促进人工智能气象应用服务健康有序发展，规范人工智能气象应用服务，建立人工智能气象应用服务秩序，根据《中华人民共和国气象法》《中华人民共和国网络安全法》《中华人民共和国数据安全法》《网络数据安全管理条例》等有关法律法规的规定，结合气象行业实际，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域利用人工智能技术开展气象应用服务的，适用本办法。 人工智能气象应用服务提供者（以下简称提供者），是指利用人工智能技术提供气象应用服务的公民、法人和其他组织。"},{"i":3,"n":"第三条","txt":"发展人工智能气象应用，应当坚持总体国家安全观，统筹发展和安全，坚持促进创新和依法治理相结合，对人工智能气象应用服务实行包容审慎和分类分级监管。 提供人工智能气象应用服务，应当遵守法律、行政法规，尊重社会公德和伦理道德，遵循社会主义核心价值观，尊重知识产权，不得生成危害国家安全和利益以及虚假有害信息等法律、行政法规禁止的内容。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构负责指导、监督和管理全国人工智能气象应用服务工作，建立人工智能气象应用服务领域的工作协调机制。国家网信部门在职责范围内依法负责有关行政管理工作。 省、自治区、直辖市气象主管机构在上级气象主管机构和本级人民政府的领导下，负责监督和管理本行政区域内人工智能气象应用服务工作。地方网信部门在职责范围内依法负责本行政区域内有关行政管理工作。"},{"i":5,"n":"第五条","txt":"鼓励提供者加入气象行业组织。气象行业组织应当加强行业自律，推广应用先进技术，组织开展人员培训，提升人工智能气象应用服务行业整体水平。"},{"i":6,"n":"第六条","txt":"国务院气象主管机构应当参与国际气象领域人工智能应用服务的发展和治理，积极开展平等互利的国际合作与交流，推动参与人工智能气象应用服务相关国际规则、标准的制定。"},{"i":7,"n":"第七条","txt":"气象主管机构应当加强人工智能与气象监测预警、预报预测、数值预报等领域深度融合应用，推进人工智能气象数据、算法和算力深度发展。 气象主管机构应当推动人工智能在旅游、能源、交通、金融等气象服务领域的推广应用，构建人工智能气象应用服务场景。"},{"i":8,"n":"第八条","txt":"国务院气象主管机构建设气象领域人工智能基础数据库和专题数据集，依法推动数据要素分类分级开放共享和流通。 国务院气象主管机构应当为进入开放共享和流通环节的数据要素匹配气象数据身份标识。气象数据身份标识应当包含气象数据来源、提供者、提供内容、被提供者、使用期限、使用范围等基本信息。"},{"i":9,"n":"第九条","txt":"国务院气象主管机构按需推动人工智能气象应用服务领域的算力基础设施建设，鼓励和支持人工智能气象应用服务领域的算法模型创新，加快面向应用服务的算法模型研发与推广。"},{"i":10,"n":"第十条","txt":"气象主管机构建立健全与科研院所、高等院校、企业之间的对接交流平台，加强人工智能气象应用服务领域的产学研用深度融合，构建人工智能气象应用服务协同创新机制。"},{"i":11,"n":"第十一条","txt":"国务院气象主管机构建立完善人工智能气象应用服务的成果转化机制，健全人工智能气象应用服务领域的知识产权保护机制，依法保护人工智能气象应用服务软件作品、商业秘密等知识产权。"},{"i":12,"n":"第十二条","txt":"气象主管机构联合科研院所、高等院校、企业共同建设人工智能气象应用服务人才实训基地，完善人才的评价与奖励机制，优化人工智能气象应用服务人才发展环境。"},{"i":13,"n":"第十三条","txt":"国务院气象主管机构推动人工智能气象应用服务相关标准建设，鼓励和支持提供者、高等院校、科研机构、企业和其他组织参与标准制定。"},{"i":14,"n":"第十四条","txt":"国务院气象主管机构建立人工智能气象应用算法和模型的质量评估机制，开展人工智能气象应用示范，推动人工智能在气象业务领域的转化、准入和应用，鼓励人工智能气象服务的应用场景开放。"},{"i":15,"n":"第十五条","txt":"从事气象信息服务活动的提供者中的法人和其他组织应当根据《气象信息服务管理办法》的规定，向其营业执照注册地的省、自治区、直辖市气象主管机构备案，并接受其监督管理。 提供具有舆论属性或者社会动员能力的人工智能气象应用服务的，应当按照国家有关规定开展算法备案和安全评估。"},{"i":16,"n":"第十六条","txt":"提供者应当通过合法渠道获取标注相应气象数据身份标识的气象数据，不得窃取或者以其他非法方式获取气象数据。 提供者应当按照国家有关规定添加人工智能生成合成内容标识，确保标识的可读性和安全性，建立信息溯源机制。 提供者应当基于应用服务类型特点，采取有效措施，提升人工智能气象应用服务的透明度，提高应用服务内容的准确性和可靠性。"},{"i":17,"n":"第十七条","txt":"提供者应当依法建立健全算法安全审核、网络安全、数据安全、信息发布审核等管理制度和技术措施，确保人工智能气象应用服务安全、稳定、持续。 提供者应当对人工智能气象应用服务进行全生命周期风险管理和控制，开展安全评估和质量评价，采取必要措施防控风险。"},{"i":18,"n":"第十八条","txt":"提供者应当设置投诉举报入口，用户发现人工智能气象应用服务存在违法行为或者安全风险的，有权通过投诉举报入口反馈，提供者应当及时受理并处理。"},{"i":19,"n":"第十九条","txt":"提供者不得向社会发布和传播非气象主管机构所属气象台站提供的公众气象预报、灾害性天气警报和气象灾害预警信号。 鼓励提供者研究形成的气象预报意见和结论提供给气象主管机构所属气象台站制作气象预报时参考。"},{"i":20,"n":"第二十条","txt":"气象主管机构可以通过指导约谈等措施促进公民、法人和其他组织依法开展人工智能气象应用服务。"},{"i":21,"n":"第二十一条","txt":"气象主管机构可以进入相关应用服务现场开展监督检查，有权要求提供者提供气象数据身份标识。气象主管机构工作人员对于履行职责中知悉的国家秘密、商业秘密、个人隐私和个人信息应当依法予以保密，不得泄露或者非法向他人提供。"},{"i":22,"n":"第二十二条","txt":"气象主管机构会同网信等有关部门开展人工智能气象应用服务领域的数据安全监管。 发现数据处理活动存在较大安全风险的，有关气象主管机构依法对有关公民、法人和其他组织进行约谈，并要求有关公民、法人和其他组织采取措施进行整改，消除隐患。"},{"i":23,"n":"第二十三条","txt":"人工智能气象应用服务中涉及数据出境的，应当符合法律、行政法规和国家网信部门的有关规定。 人工智能气象应用服务中涉及国家安全、国家秘密的，应当遵守国家安全和保密的法律、法规、规章和有关规定。"},{"i":24,"n":"第二十四条","txt":"任何组织和个人发现违反本办法的行为，可以向气象主管机构投诉、举报。"},{"i":25,"n":"第二十五条","txt":"人工智能气象应用服务提供者初次违法且危害后果轻微并及时改正的，可以不予行政处罚。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构依据职责责令改正，给予警告，可以处五万元以下的罚款: （一）非法向社会发布公众气象预报、灾害性天气警报、气象灾害预警信号的； （二）传播通过非法渠道获取的灾害性天气信息和气象灾害灾情的。"},{"i":27,"n":"第二十七条","txt":"有关主管部门及其工作人员不依法履行本办法规定的监督检查职责的，由其上级行政机关责令改正，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"气象主管机构、网信等有关主管部门发现人工智能气象应用服务存在其他违法行为的，在职责范围内依照相关法律法规的规定予以处理。"},{"i":29,"n":"第二十九条","txt":"本办法自2025年6月1日起施行。"}],"shengfangqiqiuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对升放气球活动的管理，保障航空飞行和人民生命财产安全，根据《通用航空飞行管制条例》及其他有关规定和升放气球管理工作的实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称气球，包括无人驾驶自由气球和系留气球。 无人驾驶自由气球，是指无动力驱动、无人操纵、轻于空气、总质量大于4千克自由漂移的充气物体。 系留气球，是指系留于地面物体上、直径大于1.8米或者体积容量大于3.2立方米、轻于空气的充气物体。 前述气球不包括热气球、系留式观光气球等载人气球。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事升放气球活动，应当遵守本办法及国家其他有关规定。 因气象业务从事升放气球活动，按照国务院气象主管机构的有关规定执行。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构及飞行管制等部门按照职责分工，负责管理和指导全国的升放气球活动。 地方各级气象主管机构及飞行管制等部门按照职责分工，在当地人民政府的指导和协调下，负责管理本行政区域内的升放气球活动。"},{"i":5,"n":"第五条","txt":"从事升放气球活动，应当坚持安全第一的原则，严格执行国家制定的有关技术规范、标准和规程。"},{"i":6,"n":"第六条","txt":"对升放气球单位实行资质认定制度。 未按规定取得《升放气球资质证》的单位不得从事升放气球活动。"},{"i":7,"n":"第七条","txt":"申请升放气球资质的单位应当具备下列条件： (一)有独立的法人资格； (二)有固定的工作场所，危险气体的运输、使用和存放必须符合国家规定； (三)有四名以上作业人员，其中至少有一名具有相关专业中级以上技术职称的人员； (四)有必需的器材和设备； (五)有健全的安全保障制度和措施。"},{"i":8,"n":"第八条","txt":"申请从事升放气球活动的单位，应当向所在地的设区的市级或者省、自治区、直辖市气象主管机构（以下简称认定机构）提出申请，并提供下列申请材料： (一)升放气球资质证申请表； (二)作业人员登记表； (三)升放气球的器材和设备清单； (四)安全保障责任制度和措施； (五)法律、法规规定的其他材料。 认定机构应当根据《行政许可法》第三十二条的规定，决定受理或者不予受理申请，并出具书面凭证。不予受理申请的，应当说明理由。"},{"i":9,"n":"第九条","txt":"认定机构受理申请后，应当根据需要，指派两名以上工作人员进行现场核查。"},{"i":10,"n":"第十条","txt":"申请单位的申请符合法定条件的，认定机构应当自受理申请之日起二十日内作出行政许可决定，自决定之日起十日内向申请单位颁发加盖认定机构印章的《升放气球资质证》。二十日内不能作出决定的，经本级气象主管机构负责人批准，可以延长十日，并将延长期限的理由告知申请人。 认定机构依法作出不予行政许可的书面决定的，应当说明理由，并告知申请单位依法享有申请行政复议或者提起行政诉讼的权利。"},{"i":11,"n":"第十一条","txt":"《升放气球资质证》有效期为五年，并实行年度报告制度。取得资质的单位，应当在每年的六月底前将上一年度升放气球年度报告报认定机构。 年度报告应当包括持续符合资质认定条件和要求、遵守技术标准和规范、作业人员安全培训情况、升放气球活动等情况。 认定机构应当对年度报告内容进行抽查，并公开抽查结果。 取得升放气球资质的单位，应当在资质有效期届满三十日前向原认定机构申请延续。认定机构应当根据该单位的申请、年度报告及信用管理等有关情况，在有效期届满前作出是否准予延续的决定。"},{"i":12,"n":"第十二条","txt":"取得升放气球资质的单位，出现下列行为之一的，由认定机构注销其资质证： (一)有效期届满未延续的； (二)法人依法终止的； (三)资质证书依法被撤销的； (四)法律、法规规定的应当注销行政许可的其他情形。"},{"i":13,"n":"第十三条","txt":"升放气球活动实行许可制度。 升放气球单位升放无人驾驶自由气球至少提前五日、升放系留气球至少提前两日向升放所在地的县级以上地方气象主管机构（以下简称许可机构）提出申请，并按要求如实填写升放气球作业申报表。"},{"i":14,"n":"第十四条","txt":"申请材料不齐全或者不符合有关规定的，许可机构应当当场告知申请单位需要补正的全部内容，并按照《行政许可法》第三十二条第一款第一项、第二项、第三项、第五项的规定，决定受理或者不予受理申请，出具书面凭证。不予受理申请的，应当说明理由。"},{"i":15,"n":"第十五条","txt":"受理申请的许可机构应当按照职责，对申请单位的资质、升放环境、升放期间的气象条件等条件进行审查。符合规定条件的，许可机构应当自受理申请之日起两日内作出书面行政许可决定。 许可机构依法作出不予行政许可的书面决定，应当说明理由，并告知申请单位依法享有申请行政复议或者提起行政诉讼的权利。 取消升放活动的，升放气球单位应当及时向许可机构报告；更改升放时间、地点或者数量的，升放气球单位应当按照本办法规定重新提出申请。"},{"i":16,"n":"第十六条","txt":"升放无人驾驶自由气球，应当在拟升放两日前持本办法第十五条规定的批准文件向当地飞行管制部门提出升放申请。"},{"i":17,"n":"第十七条","txt":"升放气球活动必须在许可机构批准的范围内进行。 禁止在依法划设的机场范围内和机场净空保护区域内升放无人驾驶自由气球或者系留气球，但是国家另有规定的除外。"},{"i":18,"n":"第十八条","txt":"升放气球必须符合下列安全要求： (一)储运气体及充灌、回收气球必须严格遵守消防、危险化学品安全使用管理等有关规定； (二)升放气球的地点应当与高大建筑物、树木、架空电线、通信线和其他障碍物保持安全的距离，避免碰撞、摩擦和缠绕等； (三)在升放气球的球体及其附属物上必须设置识别标志； (四)升放气球必须符合适宜的气象条件； (五)系留气球升放的高度不得高于地面150米，但是低于距其水平距离50米范围内建筑物顶部的除外； (六) 升放系留气球必须确保系留牢固； (七) 系留气球升放的高度超过地面50米的，必须加装快速放气装置。"},{"i":19,"n":"第十九条","txt":"升放气球必须由取得《升放气球资质证》单位的作业人员进行操作，现场应当有专人值守，以预防和处理意外情况。 取得《升放气球资质证》的单位应当定期对作业人员进行安全操作培训。"},{"i":20,"n":"第二十条","txt":"县级以上气象主管机构负责对本行政区域内升放气球活动的监督管理。 升放气球单位应当主动接受气象主管机构的监督管理与安全检查，并按照要求做好有关工作。 任何单位和个人不得委托无《升放气球资质证》的单位升放系留气球或者无人驾驶自由气球。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市气象主管机构应当对本行政区域内取得升放气球资质的单位建立信用管理制度，县级以上地方气象主管机构将升放气球活动和监督管理等信息纳入信用档案。"},{"i":22,"n":"第二十二条","txt":"县级以上气象主管机构可以对升放气球场所进行实地检查。检查时，检查人员可以查阅或者要求被检查单位报送有关材料；被检查单位应当如实提供有关情况和材料。"},{"i":23,"n":"第二十三条","txt":"县级以上气象主管机构应当对下列内容进行监督检查： (一)升放气球单位是否具有资质证； (二)升放气球单位是否按照规定程序进行申报并获得批准； (三)升放气球的时间、地点、种类和数量等是否与所批准的内容相符合； (四)升放气球单位和作业人员、技术人员是否遵守有关技术规范、标准和规程； (五)升放现场是否有专人值守； (六)气球的升放是否符合有关安全要求。"},{"i":24,"n":"第二十四条","txt":"在升放气球过程中，如发生无人驾驶自由气球非正常运行、系留气球意外脱离系留或者其他安全事故，升放单位应当立即停止升放活动，及时向飞行管制部门、所在地气象主管机构报告，并做好有关事故的处理工作。 加装快速放气装置的系留气球意外脱离系留时，升放系留气球的单位应当在保证地面人员、财产安全的条件下，快速启动放气装置。"},{"i":25,"n":"第二十五条","txt":"申请单位隐瞒有关情况、提供虚假材料申请资质认定或者升放活动许可的，认定机构或者许可机构不予受理或者不予许可，并给予警告。申请单位在一年内不得再次申请资质认定或者升放活动许可。"},{"i":26,"n":"第二十六条","txt":"被许可单位以欺骗、贿赂等不正当手段取得资质或者升放活动许可的，认定机构或者许可机构按照权限给予警告，可以处三万元以下罚款，撤销其《升放气球资质证》或者升放活动许可决定；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，有下列行为之一的，由县级以上气象主管机构按照权限责令改正，给予警告，可以处三万元以下罚款；给他人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）涂改、伪造、倒卖、出租、出借、挂靠、转让《升放气球资质证》或者许可文件的； （二）向监督检查机构隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况的真实材料的。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，未取得《升放气球资质证》从事升放气球活动，由县级以上气象主管机构按照权限责令停止违法行为，处一万元以上三万元以下罚款；给他人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，有下列行为之一的，按照《通用航空飞行管制条例》第四十三条的规定进行处罚： (一)未经批准擅自升放的； (二)未按照批准的申请升放的； (三)未按照规定设置识别标志的； (四)未及时报告异常升放动态或者系留气球意外脱离时未按照规定及时报告的； (五)在规定的禁止区域内升放的。"},{"i":30,"n":"第三十条","txt":"违反本办法规定，有下列行为之一的，由县级以上气象主管机构按照权限责令改正，给予警告，可以处一万元以下罚款；情节严重的，处一万元以上三万元以下罚款；造成重大事故或者严重后果的，依照《安全生产法》有关规定处罚；构成犯罪的，依法追究刑事责任： (一)未按期提交年度报告或者提交的年度报告存在虚假内容的； (二)违反升放气球技术规范和标准的； (三)未指定专人值守的； (四)升放高度超过地面50米的系留气球未加装快速放气装置的； (五)利用气球开展各种活动的单位和个人，使用无《升放气球资质证》的单位升放气球的； (六)在安全事故发生后隐瞒不报、谎报、故意迟延不报、故意破坏现场，或者拒绝接受调查以及拒绝提供有关情况和资料的； (七)违反升放气球安全要求的其他行为。"},{"i":31,"n":"第三十一条","txt":"气象主管机构的工作人员弄虚作假、玩忽职守、滥用职权、徇私舞弊，尚不构成犯罪的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"本办法规定的时间期限以工作日计算，不含法定节假日。"},{"i":33,"n":"第三十三条","txt":"《升放气球资质证》由国务院气象主管机构监制。"},{"i":34,"n":"第三十四条","txt":"本办法自2021年1月1日起施行。2004年12月16日发布的中国气象局第9号令《施放气球管理办法》同时废止。"}],"xinjiankuojiangaijianjianshegongchengbimianweihaiqc0f4e1":[{"i":1,"n":"第一条","txt":"为规范新建、扩建、改建建设工程避免危害气象探测环境行政许可行为，保护公民、法人和其他组织的合法权益，保障和监督气象主管机构有效实施行政管理，根据《中华人民共和国气象法》、《中华人民共和国行政许可法》、《气象设施和气象探测环境保护条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在大气本底站、国家基准气候站、国家基本气象站、国家一般气象站、高空气象观测站、天气雷达站、气象卫星地面站气象探测环境保护范围内实施新建、扩建、改建建设工程避免危害气象探测环境的行政许可，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法规定的气象台站气象探测环境保护范围和建设工程类别应当按照相应的气象台站气象探测环境保护和建设工程的有关法律法规和国家标准执行。 省、自治区、直辖市气象主管机构应将本行政区域内各类气象台站的位置及其探测环境保护范围向社会公布。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构负责全国新建、扩建、改建建设工程避免危害气象探测环境行政许可的监督管理。 省、自治区、直辖市气象主管机构负责本行政区域内新建、扩建、改建建设工程避免危害气象探测环境行政许可的实施和管理工作。 设区的市气象主管机构或者省直管县（市）气象主管机构负责本行政区域内新建、扩建、改建建设工程避免危害气象探测环境行政许可的初审和管理工作。"},{"i":5,"n":"第五条","txt":"申请人提交以下材料，并对申请材料的真实性负责： （一）新建、扩建、改建建设工程避免危害气象探测环境行政许可申请表； （二）申请人身份信息； （三）新建、扩建、改建建设工程与气象探测设施或观测场的相对位置示意图； （四）委托代理的，应出具委托协议。 申请人为法人或其他组织的，还应当提交新建、扩建、改建建设工程概况和规划总平面图。"},{"i":6,"n":"第六条","txt":"新建、扩建、改建建设工程避免危害气象探测环境行政许可的申请由设区的市气象主管机构或者省直管县（市）气象主管机构受理。 设区的市气象主管机构或者省直管县（市）气象主管机构应当在收到全部申请材料之日起五个工作日内，按照《中华人民共和国行政许可法》第三十二条和本办法第五条的规定作出受理或者不予受理的决定，并出具书面凭证。"},{"i":7,"n":"第七条","txt":"受理机构负责对申请材料进行初审，并组织现场踏勘。现场踏勘应当通知申请人或者其代理人到场，申请人或者其代理人应当在现场踏勘记录表上签署明确意见。 受理机构应当自受理之日起二十个工作日内将全部申请材料和初审意见报省、自治区、直辖市气象主管机构审批。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市气象主管机构应当对申请材料进行全面审查，必要时可组织现场复查和专家论证。经审查符合有关法律法规和标准要求的，应当在收到全部申请材料和初审意见之日起二十个工作日内作出准予许可的书面决定；不符合要求的，作出不予许可的书面决定，并说明理由。 二十个工作日内不能作出决定的，经本级气象主管机构负责人批准，可以延长十个工作日，并应当将延长期限的理由书面告知申请人。 行政许可决定作出后，应当在十个工作日内送达申请人。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市气象主管机构、设区的市气象主管机构或者省直管县（市）气象主管机构在审批过程中需要按照《中华人民共和国行政许可法》第四十五条规定进行技术审查（含现场踏勘）的，所需时间不计入审批时间内。 技术审查（含现场踏勘）时间一般不超过一个月。省、自治区、直辖市气象主管机构、设区的市气象主管机构或者省直管县（市）气象主管机构应当将所需时间书面告知申请人。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市气象主管机构在作出许可决定前，应当告知申请人、利害关系人享有要求听证的权利。申请人要求听证的，应当自接到告知听证通知之日起五个工作日内以书面形式提出。听证程序按照《中华人民共和国行政许可法》第四十八条要求进行。 省、自治区、直辖市对听证另有规定的，从其规定。"},{"i":11,"n":"第十一条","txt":"取得行政许可后，如果建设规划或工程设计发生变化的，申请人应当重新申请。"},{"i":12,"n":"第十二条","txt":"地方各级气象主管机构应当对气象探测环境保护范围内的新建、扩建、改建建设工程避免危害气象探测环境行政许可事项的活动进行监督检查，及时了解情况并向省、自治区、直辖市气象主管机构报告。"},{"i":13,"n":"第十三条","txt":"公民、法人或者其他组织发现在气象探测环境保护范围内违法从事新建、扩建、改建建设工程避免危害气象探测环境行政许可事项的活动，有权向气象主管机构举报，气象主管机构接到举报后应当及时核实、处理。"},{"i":14,"n":"第十四条","txt":"未取得新建、扩建、改建建设工程避免危害气象探测环境行政许可的，或者取得许可后不按规定进行建设，造成气象探测环境遭到破坏的，按照《气象法》第三十五条、《气象设施和气象探测环境保护条例》第二十五条予以处罚。"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市气象主管机构可以根据本办法制定实施细则，并报国务院气象主管机构备案。"},{"i":16,"n":"第十六条","txt":"本办法自2016年9月1日起施行。"}],"qihoukexingxinglunzhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对气候可行性论证的管理，规范气候可行性论证活动，合理开发利用气候资源，避免或者减轻规划和建设项目实施后可能受气象灾害、气候变化的影响，或者可能对局地气候产生的影响，根据《中华人民共和国气象法》等有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域从事气候可行性论证活动的组织和个人，应当遵守本办法。 本办法所称气候可行性论证，是指对与气候条件密切相关的规划和建设项目进行气候适宜性、风险性以及可能对局地气候产生影响的分析、评估活动。"},{"i":3,"n":"第三条","txt":"国务院气象主管机构组织管理全国的气候可行性论证工作。 地方各级气象主管机构在上级气象主管机构和本级人民政府的领导下，组织管理本行政区域内的气候可行性论证工作。 其他有关部门和单位应当配合气象主管机构做好气候可行性论证工作。"},{"i":4,"n":"第四条","txt":"与气候条件密切相关的下列规划和建设项目应当进行气候可行性论证： （一）城乡规划、重点领域或者区域发展建设规划； （二）重大基础设施、公共工程和大型工程建设项目； （三）重大区域性经济开发、区域农（牧）业结构调整建设项目； （四）大型太阳能、风能等气候资源开发利用建设项目； （五）其他依法应当进行气候可行性论证的规划和建设项目。"},{"i":5,"n":"第五条","txt":"气象主管机构应当根据城乡规划、重点领域或者区域发展建设规划编制需要，组织开展气候可行性论证。 规划编制单位在编制规划时应当充分考虑气候可行性论证结论。"},{"i":6,"n":"第六条","txt":"项目建设单位在组织本办法第四条第（二）项至第（五）项规定的建设项目时，应当进行气候可行性论证。"},{"i":7,"n":"第七条","txt":"建设项目的气候可行性论证应当由国务院气象主管机构确认的具备相应论证能力的机构（以下称论证机构）进行。 论证机构进行建设项目的气候可行性论证时应当编制气候可行性论证报告，并保证报告的真实性、科学性。"},{"i":8,"n":"第八条","txt":"气候可行性论证报告应当包括下列内容： （一）规划或者建设项目概况； （二）基础资料来源及其代表性、可靠性说明，通过现场探测所取得的资料，还应当对探测仪器、探测方法和探测环境进行说明； （三）气候可行性论证所依据的标准、规范、规程和方法； （四）规划或者建设项目所在区域的气候背景分析； （五）气候适宜性、风险性以及可能对局地气候产生影响的评估，极端天气气候事件出现概率； （六）预防或者减轻影响的对策和建议； （七）论证结论和适用性说明； （八）其他有关内容。"},{"i":9,"n":"第九条","txt":"论证机构进行气候可行性论证，应当使用气象主管机构直接提供的气象资料或者经过省、自治区、直辖市气象主管机构审查的气象资料。 现有气象资料不能满足气候可行性论证需要的，应当开展现场气象探测，探测仪器、探测方法和探测环境应当遵守气象探测有关法律、法规、规章和标准、规范、规程。 现场气象探测所获取的气象资料应当按照国家有关规定向国务院气象主管机构或者省、自治区、直辖市气象主管机构汇交。"},{"i":10,"n":"第十条","txt":"气候可行性论证采用的技术方法应当符合现行的国家或者有关行业、地方制定的标准、规范和规程。 现行的标准、规范和规程不能满足需要的，应当采用经过有关领域专家评审的成熟理论和技术方法。"},{"i":11,"n":"第十一条","txt":"气象主管机构或者其委托的机构应当组织专家对建设项目的气候可行性论证报告进行评审，并出具书面评审意见。 下列建设项目的气候可行性论证报告由国务院气象主管机构或者其委托的机构组织专家进行评审： （一）国家重大基础设施、公共工程和大型工程建设项目； （二）跨省、自治区、直辖市行政区域的工程建设项目； （三）法律、法规、规章规定的其他应当由国务院气象主管机构评审的建设项目。 前款规定以外的气候可行性论证报告由建设项目所在地的省、自治区、直辖市气象主管机构或者其委托的机构组织专家进行评审。 评审通过的报告和评审意见作为建设项目的立项、设计或者审批的依据。"},{"i":12,"n":"第十二条","txt":"必须进行气候可行性论证的建设项目，属于审批制和核准制的，由政府投资主管部门在审核项目可行性研究报告和申请报告前征求同级气象主管机构的专业性意见。属于备案制的，按照相关备案管理办法执行。"},{"i":13,"n":"第十三条","txt":"负责规划或者建设项目审批、核准的部门应当将气候可行性论证结果和专家评审通过的气候可行性论证报告纳入规划或者建设项目可行性研究报告的审查内容，统筹考虑气候可行性论证报告结论。对可行性研究报告或者申请报告中未包括气候可行性论证内容的建设项目，不予审批或者核准。 咨询评估单位的评估报告中应当包括对气候可行性论证报告的评估意见。 其他有关法律、法规有特殊规定的，按照其相应的规定执行。"},{"i":14,"n":"第十四条","txt":"在气候可行性论证活动中禁止下列行为： （一）伪造气象资料或者其他原始资料的； （二）出具虚假论证报告的； （三）涂改、伪造气候可行性论证报告书面评审意见的。"},{"i":15,"n":"第十五条","txt":"国家鼓励和支持有关气候可行性论证的科学技术研究和开发，推广应用气候可行性论证科技研究成果，提高气候可行性论证技术水平。"},{"i":16,"n":"第十六条","txt":"国务院气象主管机构应当会同有关部门根据经济社会发展需要和气候变化状况，制定和完善与气候可行性论证有关的标准、规范和规程。 在气候可行性论证活动中应用的成熟理论和技术方法应当尽快转化为标准、规范和规程。"},{"i":17,"n":"第十七条","txt":"违反本办法规定，不具备气候可行性论证能力的机构从事气候可行性论证活动的，由县级以上气象主管机构按照权限责令改正，给予警告，可以处三万元以下罚款；造成损失的，依法承担赔偿责任。"},{"i":18,"n":"第十八条","txt":"违反本办法规定，有下列行为之一的，由县级以上气象主管机构按照权限责令改正，给予警告，可以处三万元以下罚款；情节严重的，由国务院气象主管机构进行通报；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）使用的气象资料，不是气象主管机构直接提供或者未经省、自治区、直辖市气象主管机构审查的； （二）伪造气象资料或者其他原始资料的； （三）出具虚假论证报告的； （四）涂改、伪造气候可行性论证报告书面评审意见的。"},{"i":19,"n":"第十九条","txt":"违反本办法规定，项目建设单位有下列行为之一的，由县级以上气象主管机构按照权限责令改正，给予警告，可以处三万元以下罚款；构成犯罪的，依法追究刑事责任： （一）应当进行气候可行性论证的建设项目，未经气候可行性论证的； （二）委托不具备气候可行性论证能力的机构进行气候可行性论证的。"},{"i":20,"n":"第二十条","txt":"气象主管机构以及论证机构的工作人员在气候可行性论证工作中玩忽职守、滥用职权、徇私舞弊，尚不构成犯罪的，由所在单位给予处分；构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"境外组织、机构和个人在中华人民共和国领域和中华人民共和国管辖的其他海域从事气候可行性论证活动，应当与国务院气象主管机构确认的论证机构合作进行，并经国务院气象主管机构批准。 经批准从事气候可行性论证活动的境外组织、机构和个人，应当向所在地的省、自治区、直辖市气象主管机构备案并接受监督管理。"},{"i":22,"n":"第二十二条","txt":"本办法自2009年1月1日起施行。"}],"qixiangzhuanyongjishuzhuangbeishiyongxukeguanlibane58837":[{"i":1,"n":"第一条","txt":"为了保证气象专用技术装备质量，满足气象业务和气象灾害防御的需要，规范气象专用技术装备使用许可行为，依据《中华人民共和国气象法》《中华人民共和国行政许可法》和《人工影响天气管理条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域内，气象专用技术装备使用许可的实施和监督管理，应当遵守本办法。 本办法所称气象专用技术装备，是指专门用于气象探测、预报、服务以及人工影响天气、空间天气等气象业务的气象设备、仪器、仪表、消耗器材及相应软件系统。"},{"i":3,"n":"第三条","txt":"国务院气象主管机构负责气象专用技术装备使用许可的实施和监督管理。 地方各级气象主管机构负责本行政区域内气象专用技术装备使用的监督管理。"},{"i":4,"n":"第四条","txt":"实施气象专用技术装备使用许可，应当遵循公开、公平、公正原则。"},{"i":5,"n":"第五条","txt":"在气象业务、工程设计建设中，应当使用具备有效许可证的气象专用技术装备。"},{"i":6,"n":"第六条","txt":"国务院气象主管机构应当定期公告气象专用技术装备目录和取得或者注销、撤销许可的名录。"},{"i":7,"n":"第七条","txt":"气象专用技术装备使用许可应当由生产者提出申请，并具备下列条件： （一）具有法人资格； （二）通过质量管理体系认证； （三）产品满足国家标准、气象行业标准或者国务院气象主管机构规定的技术要求； （四）具备与所生产产品相适应的生产、检测、销售、服务等体系； （五）符合国家其他有关规定。 申请人工影响天气作业用火箭发射装置、炮弹、火箭弹三类设备使用许可证的，应当符合国家武器装备、民用爆炸物品的相关规定和国家有关强制性技术标准。"},{"i":8,"n":"第八条","txt":"申请人应当向国务院气象主管机构提供下列申请材料： （一）气象专用技术装备使用许可证申请表； （二）产品技术文件，应包括下列材料：产品技术指标和配置一览表、企业标准、成套技术图纸、工艺文件、标准化审查报告、经济分析报告、使用说明书； （三）第七条第三项到第五项的相关材料。 申请人应当对所提交的申请材料的真实性负责。"},{"i":9,"n":"第九条","txt":"国务院气象主管机构应当在收到全部申请材料之日起五个工作日内，按照《中华人民共和国行政许可法》第三十二条和本办法规定的条件作出受理或者不予受理的书面决定。对不予受理的，应当书面说明理由。"},{"i":10,"n":"第十条","txt":"国务院气象主管机构受理申请后，对申请材料进行审查并根据需要指派两名以上工作人员对申请材料的实质内容进行实地核查。"},{"i":11,"n":"第十一条","txt":"对受理的申请，国务院气象主管机构应当委托符合下列基本条件的检测机构对产品进行检定、检测： （一）具有国家法定授权的气象计量机构或者认证认可监督管理部门颁发资质的检测机构； （二）具备技术标准要求的检验测试手段和基本环境条件； （三）用于检测的标准、设备和仪器经过计量主管部门检定和校准； （四）具有相应资格的测试技术人员； （五）具有完善的运行和维护制度。"},{"i":12,"n":"第十二条","txt":"检测机构应当按照国家有关标准或者国务院气象主管机构规定的技术要求，完成检定和检测后，提交书面检测报告。检测机构应当对检测数据和结论的真实性负责，并对相关技术文件保密。 人工影响天气作业用火箭发射装置、炮弹、火箭弹，还应由国家级人工影响天气业务单位出具业务性试用报告。"},{"i":13,"n":"第十三条","txt":"国务院气象主管机构应当依据检测机构出具的报告对申请材料进行全面审查，在受理之日起二十个工作日内作出是否准予行政许可的决定。审查合格的，依法作出准予行政许可的决定；审查不合格的，依法作出不予行政许可的书面决定，出具《不予行政许可决定书》，同时说明理由并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":14,"n":"第十四条","txt":"国务院气象主管机构作出准予行政许可决定的，应当自作出决定之日起十个工作日内向申请人颁发《气象专用技术装备使用许可证》。 《气象专用技术装备使用许可证》分正本和副本，应当载明产品名称、规格型号、生产单位、法定代表人、单位地址、许可证编号、有效期限、发证日期、产品配置清单等内容，并加盖国务院气象主管机构的印章。《气象专用技术装备使用许可证》的有效期为四年。"},{"i":15,"n":"第十五条","txt":"《气象专用技术装备使用许可证》有效期届满需要延期的，被许可人应当在有效期届满六十日前，向国务院气象主管机构提出延续申请。国务院气象主管机构应当在有效期届满前完成审查。符合条件的，予以延续；不符合条件的，不予以延续，并书面告知申请人。"},{"i":16,"n":"第十六条","txt":"取得《气象专用技术装备使用许可证》的单位在其证书有效期内，单位名称、地址、法定代表人等发生变更的，应当在工商行政管理部门变更登记后三十日内，向国务院气象主管机构提出变更申请。"},{"i":17,"n":"第十七条","txt":"国务院气象主管机构应当将申请人办理《气象专用技术装备使用许可证》的有关资料按照档案管理的有关规定及时归档，公众有权查阅。"},{"i":18,"n":"第十八条","txt":"国务院气象主管机构应当对取得许可的气象专用技术装备进行监督检查。 地方各级气象主管机构应当对气象业务使用的气象专用技术装备的购买和使用情况进行定期检查，并将检查情况逐级报告上级气象主管机构。 对监督检查中发现的问题，国务院气象主管机构责令被许可人或者购买、使用单位限期整改。"},{"i":19,"n":"第十九条","txt":"任何组织和个人不得涂改、伪造、倒卖、出租、出借《气象专用技术装备使用许可证》。"},{"i":20,"n":"第二十条","txt":"任何单位和个人对《气象专用技术装备使用许可证》发放和管理过程中的违法行为有权进行举报，国务院气象主管机构应当及时核实、处理。"},{"i":21,"n":"第二十一条","txt":"产品出现重大质量问题、被许可人对存在的问题拒不整改或者整改达不到要求的，国务院气象主管机构应当根据利害关系人的申请或者依据职权作出撤销行政许可的决定。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，国务院气象主管机构应当依法办理有关行政许可的注销手续： （一）许可有效期届满未申请延续的； （二）法人依法终止的； （三）许可依法被撤销的； （四）法律、法规规定的应当注销许可的其他情形。"},{"i":23,"n":"第二十三条","txt":"申请人隐瞒有关情况，提供虚假材料，申请气象专用技术装备使用许可的，国务院气象主管机构不予受理或者不予许可，并给予警告。申请人在一年内不得再次申请该项许可。"},{"i":24,"n":"第二十四条","txt":"被许可人以欺骗、贿赂等不正当手段取得气象专用技术装备使用许可的，国务院气象主管机构给予警告，撤销其许可，申请人在三年内不得再次申请该项许可；给他人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，涂改、伪造、倒卖、出租、出借《气象专用技术装备使用许可证》的，国务院气象主管机构给予警告，撤销其许可；给他人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，使用未经许可或者被注销、撤销许可后生产的气象专用技术装备，并造成危害的，由县级以上气象主管机构按照《气象法》第三十六条的规定进行处罚。"},{"i":27,"n":"第二十七条","txt":"本办法自2016年6月1日起施行。2006年11月22日中国气象局公布的《气象专用技术装备使用许可管理办法》（中国气象局令第14号）同时废止。 依据中国气象局令第14号已经取得的《气象专用技术装备使用许可证》在有效期内继续有效。"}],"qixiangxinxifuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了促进气象信息服务发展，培育气象信息服务市场，规范气象信息服务活动，满足经济社会发展和人民生活对气象信息服务的需求，根据《中华人民共和国气象法》和《气象灾害防御条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域开展气象信息服务活动和进行监督管理，适用本办法。 公众气象预报、灾害性天气警报和气象灾害预警信号的发布按照国家有关规定执行。"},{"i":3,"n":"第三条","txt":"本办法所称气象信息服务，是指气象信息服务单位利用气象资料和气象预报产品，开展面向用户需求的信息服务活动。 本办法所称气象信息服务单位是指依法设立并从事气象信息服务的法人和其他组织。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构负责全国气象信息服务活动的监督管理工作。 地方各级气象主管机构在上级气象主管机构和本级人民政府的领导下，负责本行政区域内气象信息服务活动的监督管理工作。"},{"i":5,"n":"第五条","txt":"国家鼓励依法开展气象信息服务活动，支持与气象信息服务有关的科研开发和成果推广应用，引导和吸引社会资本支持气象信息产业发展。"},{"i":6,"n":"第六条","txt":"气象信息服务应当遵循自愿公平、诚实信用原则，不得损害国家利益、公共利益和他人的合法权益。"},{"i":7,"n":"第七条","txt":"国务院气象主管机构应当建立全国统一的气象信息服务单位备案统计与公示制度。 气象信息服务单位应当向其营业执照注册地的省、自治区、直辖市气象主管机构备案，并接受其监督管理。本办法实行前成立的，应当自实行之日起六个月内办理备案；本办法实行后成立的，应当自领取营业执照之日起三个月内办理备案。"},{"i":8,"n":"第八条","txt":"气象信息服务单位备案应当提供以下材料： （一）法定代表人身份信息； （二）主要技术人员信息； （三）信息服务提供方式和范围说明。"},{"i":9,"n":"第九条","txt":"从事气象信息服务的单位应当遵守下列要求： （一）使用合法渠道获得的气象资料和气象预报产品； （二）建立业务规范和管理制度； （三）遵守气象有关技术标准、规范和规程。"},{"i":10,"n":"第十条","txt":"鼓励建立气象信息服务行业组织。气象信息服务行业组织应当对气象信息服务活动实行行业自律管理，并接受省、自治区、直辖市气象主管机构的业务指导和行业监管。"},{"i":11,"n":"第十一条","txt":"气象信息服务行业组织应当制定气象信息服务行业自律制度和执业准则，促进气象信息服务行业健康发展。"},{"i":12,"n":"第十二条","txt":"国务院气象主管机构或者省、自治区、直辖市气象主管机构应当按照国家有关规定组织或者委托第三方机构对气象信息服务单位开展的气象信息服务质量进行定期评价，并公示评价结果。"},{"i":13,"n":"第十三条","txt":"国务院气象主管机构或者省、自治区、直辖市气象主管机构应当通过政府信息公开、气象信息服务单位主动申报、社会公众举报信息等多种渠道，广泛征集气象信息服务单位的信用信息，经核实后向社会发布。"},{"i":14,"n":"第十四条","txt":"国务院气象主管机构应当建立气象资料汇交共享平台，并制定数据汇交制度。 国务院气象主管机构应当制定基本气象资料和产品清单并向社会公布。从事气象信息服务单位可无偿获取基本气象资料和产品。"},{"i":15,"n":"第十五条","txt":"开展气象信息服务的单位应当充分利用气象主管机构所属的气象台提供的基本气象资料,避免重复建设气象探测站（点）。 确需建站获取资料的，建站单位应当将拟建气象探测站（点）的地理位置、经纬度坐标、探测气象要素类型、仪器设备、资料传输、存储方式、目的用途和探测时段等相关信息报探测站（点）所在地设区的市级以上气象主管机构备案，并按照国家有关规定汇交所获得的气象探测资料，气象主管机构应当出具汇交凭证。"},{"i":16,"n":"第十六条","txt":"禁止气象信息服务单位从事下列活动： （一）向社会发布公众气象预报、灾害性天气警报和气象灾害预警信号； （二）损害国家安全、公共利益和他人合法权益的行为； （三）擅自在国防及军事设施、军事敏感区域、尚未对外开放地区和其他涉及国家安全的区域设立气象探测站（点）； （四）法律法规禁止的其他气象信息服务活动。"},{"i":17,"n":"第十七条","txt":"外国组织和个人在华从事气象信息服务活动，应当按照气象法和有关外商投资的法律法规办理。"},{"i":18,"n":"第十八条","txt":"违反本办法规定，有下列行为之一的，由县级以上气象主管机构责令限期改正，拒不改正的，给予警告，可以并处3万元以下罚款，处罚结果纳入气象信息服务单位信用信息统计系统并向社会公示： （一）使用的气象资料不是气象主管机构所属的气象台提供，或者不能证明是其他合法渠道获得的； （二）从事气象信息服务，逾期未向所在地的省、自治区、直辖市气象主管机构备案的或者提供虚假备案材料的； （三）开展气象探测活动，未向设区的市级以上气象主管机构备案，或者未按照国家有关规定汇交所获得的气象探测资料的； （四）冒用他人名义开展气象信息服务的、损害公共利益和他人合法权益的。"},{"i":19,"n":"第十九条","txt":"外国组织和个人未经气象主管机构批准，擅自从事气象信息服务活动的，由有关气象主管机构责令改正，给予警告，并处3万元以下罚款。 气象信息服务活动中有危害国家安全和国家秘密行为，违反有关法律法规的，由国家安全、保密部门依法处理；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"违反本办法规定，向社会发布公众气象预报、灾害性天气警报和气象灾害预警信号的，按照《中华人民共和国气象法》和《气象灾害防御条例》等有关法律、法规的规定进行处罚。"},{"i":21,"n":"第二十一条","txt":"本办法自2015年6月1日起施行。"}],"qixiangtaizhanqianjianhangzhengxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范气象台站迁建行政许可行为，保护公民、法人和其他组织的合法权益，保障和监督气象主管机构有效实施行政管理，根据《中华人民共和国行政许可法》、《中华人民共和国气象法》、《气象设施和气象探测环境保护条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于因国家重点工程建设或者城市（镇）总体规划变化，确实无法避免影响气象探测环境，且无法采取补救措施，需要迁建气象台站的行政许可。 本办法所称迁建，是指将气象台站的观测场所、探测设施及配套的附属和基础设施等从现址迁移到新址的活动。"},{"i":3,"n":"第三条","txt":"国务院气象主管机构负责大气本底站、国家基准气候站和国家基本气象站迁建行政许可的审批和管理，并对其他气象台站迁建行政许可行为进行监督管理。 省、自治区、直辖市气象主管机构负责本行政区域内其他气象台站迁建行政许可的审批和管理，并承担大气本底站、国家基准气候站和国家基本气象站迁建行政许可的初审和管理。"},{"i":4,"n":"第四条","txt":"申请迁建气象台站的，应当由建设单位或者县级以上地方人民政府向本省、自治区、直辖市气象主管机构提出申请。"},{"i":5,"n":"第五条","txt":"拟迁新址必须同时满足以下要求： （一）能够代表现址所在区域的天气气候特征； （二）符合全国气象观测站网布局； （三）符合法律、法规、标准和国务院气象主管机构对气象探测环境的技术规范和管理规定； （四）土地符合建设用地要求，取得土地使用权，占地面积满足观测场地、探测设施、业务用房和辅助用房以及配套设施的布局要求，并预留与气象台站功能相适应的业务发展空间； （五）具备必要的供电、供水、交通、通信等基础条件； （六）涉及无线电业务的，符合《中华人民共和国无线电管理条例》的相关规定。"},{"i":6,"n":"第六条","txt":"申请人在提出申请时，应向受理机构提供以下材料： （一）气象台站迁建申请表； （二）气象台站选址报告书； （三）委托代理的，应出具代理委托函； （四）申请人对所提供材料真实性负责的承诺。"},{"i":7,"n":"第七条","txt":"迁建气象台站的申请由省、自治区、直辖市气象主管机构受理。 省、自治区、直辖市气象主管机构应当在收到全部申请材料之日起五个工作日内，按照《中华人民共和国行政许可法》第三十二条的规定作出受理或者不予受理的书面决定，并出具书面凭证。对于不予受理的，应当书面说明理由。"},{"i":8,"n":"第八条","txt":"申请迁建大气本底站、国家基准气候站和国家基本气象站的，省、自治区、直辖市气象主管机构应当自受理之日起二十个工作日内完成初审，并签署意见后报送国务院气象主管机构审批。国务院气象主管机构应当自收到申请材料后二十个工作日内作出决定。 申请迁建其他气象台站的，省、自治区、直辖市气象主管机构应当自受理之日起二十个工作日内作出决定。 二十个工作日内不能作出决定的，按照《中华人民共和国行政许可法》第四十二条规定执行。"},{"i":9,"n":"第九条","txt":"国务院或省、自治区、直辖市气象主管机构在审批过程中需要按照《中华人民共和国行政许可法》第四十五条规定进行技术审查（含现场踏勘）的，所需时间不计入审批时间内。 技术审查（含现场踏勘）时间一般不超过三个月。国务院或省、自治区、直辖市气象主管机构应当将所需时间书面告知申请人。"},{"i":10,"n":"第十条","txt":"申请人依法享有要求听证的权利，国务院或省、自治区、直辖市气象主管机构在作出直接涉及申请人与他人之间重大利益关系的许可决定前，应当告知申请人、利害关系人享有要求听证的权利；申请人、利害关系人在被告知听证权利之日起五个工作日内提出听证申请的，国务院或省、自治区、直辖市气象主管机构应当在二十个工作日内组织听证。听证程序按照《中华人民共和国行政许可法》第四十八条规定的程序进行。 省、自治区、直辖市对听证另有规定的，从其规定。"},{"i":11,"n":"第十一条","txt":"国务院或省、自治区、直辖市气象主管机构作出行政许可决定，应当自作出决定之日起十个工作日内向申请人送达行政许可的书面决定。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市气象主管机构作出准予其他气象台站迁建的行政许可决定，应当自作出决定之日起十五个工作日内将行政许可审批材料报国务院气象主管机构备案。"},{"i":13,"n":"第十三条","txt":"行政许可的有效期为三年。作出行政许可决定的气象主管机构，应当在行政许可决定中注明行政许可有效期的截止时间。申请人应当在行政许可有效期内按照基本建设程序和要求，完成气象台站建设工作，达到业务运行标准。 未在行政许可有效期内按照基本建设程序和要求，完成气象台站建设工作，达到业务运行标准的，申请人应当按照申请条件重新申请。"},{"i":14,"n":"第十四条","txt":"申请人取得行政许可后，如果申请内容有变更，应当重新申请。"},{"i":15,"n":"第十五条","txt":"地方各级气象主管机构应当对申请人从事气象台站迁建行政许可事项的活动进行监督检查。"},{"i":16,"n":"第十六条","txt":"新址建设工程完成后，申请人应及时向省、自治区、直辖市气象主管机构提出验收的申请，由作出许可决定的气象主管机构按照国务院气象主管机构有关业务规定组织验收。"},{"i":17,"n":"第十七条","txt":"迁建国家基准气候站、国家基本气象站和国家一般气象站的，应当按照国务院气象主管机构的规定，在新址与旧址之间进行至少一年的连续对比观测。"},{"i":18,"n":"第十八条","txt":"新址正式启用应当符合国务院气象主管机构有关业务规定。"},{"i":19,"n":"第十九条","txt":"新址启用和对比观测完成之前，应当按照《气象设施和气象探测环境保护条例》、国家有关标准和国务院气象主管机构有关要求严格保护旧址的气象探测环境。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，作出行政许可决定的气象主管机构应当依法办理气象台站迁建行政许可的注销手续： （一）未在行政许可有效期内完成气象台站迁建工作； （二）申请人的法人资格依法被中止的； （三）依照本办法被撤销行政许可的； （四）因不可抗力导致行政许可事项无法实施的； （五）法律、法规规定的应当注销行政许可的其他情形。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，作出行政许可决定的气象主管机构或者其上级气象主管机构，根据利害关系人的请求或者依据职权，可以撤销行政许可： （一）气象主管机构工作人员滥用职权、玩忽职守作出准予行政许可决定的； （二）超越法定职权作出准予行政许可决定的； （三）违反法定程序作出准予行政许可决定的； （四）对不具备申请资格或者不符合法定条件的申请人准予行政许可的； （五）依法可以撤销行政许可的其他情形。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，作出行政许可决定的气象主管机构依据职权，应当撤销行政许可： （一）被许可人以欺骗、贿赂等不正当手段取得行政许可的； （二）取得许可后不按规定进行建设的或超越许可范围的； （三）向负责监督检查的气象主管机构隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况的真实材料的； （四）法律、法规规定的其他违法行为。"},{"i":23,"n":"第二十三条","txt":"省、自治区、直辖市气象主管机构可以根据本办法制定实施细则，并报国务院气象主管机构备案。"},{"i":24,"n":"第二十四条","txt":"本办法自2016年9月1日起施行。"}],"qixiangtancehuanjinghesheshibaohubanfa":[{"i":1,"n":"第一条","txt":"为了保护气象探测环境和设施，保证气象探测工作的顺利进行，确保获取的气象探测信息具有代表性、准确性、比较性，提高气候变化的监测能力、气象预报准确率和气象服务水平，为国民经济和人民生活提供可靠保障，根据《中华人民共和国气象法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国领域和中华人民共和国管辖的其他海域内气象探测环境和设施的保护。"},{"i":3,"n":"第三条","txt":"本办法所称气象探测环境，是指为避开各种干扰保证气象探测设施准确获得气象探测信息所必需的最小距离构成的环境空间。 本办法所称气象探测设施，是指用于各类气象探测的场地、仪器、设备及其附属设施。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构负责管理全国气象探测环境和设施的保护工作。 地方各级气象主管机构在上级气象主管机构和同级人民政府的领导下，负责管理本行政区域内气象探测环境和设施的保护工作。 设有气象台站的国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门按照职责，做好本部门气象台站的探测环境和设施的保护工作，并接受同级气象主管机构的指导、监督和行业管理。 其他有关部门按照职责，配合气象主管机构做好气象探测环境和设施的保护工作。"},{"i":5,"n":"第五条","txt":"国家依法保护气象探测环境和设施。 任何组织和个人都有保护气象探测环境和设施的义务，有权检举侵占、损毁和擅自移动气象探测设施和破坏气象探测环境的行为。"},{"i":6,"n":"第六条","txt":"各级人民政府及有关部门应当加强对气象探测环境和设施保护的宣传教育，树立全民保护气象探测环境和设施的意识。 对在保护气象探测环境和设施工作中作出贡献的单位和个人，给予奖励。"},{"i":7,"n":"第七条","txt":"本办法保护以下气象探测环境和设施： (一)国家基准气候站、国家基本气象站、国家一般气象站、自动气象站、太阳辐射观测站、酸雨监测站、生态气象监测站（含农业气象站）的探测环境和设施； (二)高空气象探测站（包括风廓线仪、声雷达、激光雷达等）的探测环境和设施； (三)天气雷达站的探测环境和设施； (四)气象卫星地面接收站（含静止气象卫星地面接收站、极轨气象卫星地面接收站）、卫星测控站、卫星测距站的探测环境和设施； (五)大气本底台站、沙尘暴监测站、污染气象监测站等环境气象监测站的探测环境和设施； (六)遥感卫星辐射校正场的探测环境和设施； (七)闪电探测站的探测环境和设施； (八)GPS气象探测站外场环境； (九)气象专用频道、频率、线路、网络及相应的设施； (十)其他需要保护的气象探测环境和设施。"},{"i":8,"n":"第八条","txt":"各类气象站四周应当开阔，保持气流通畅。"},{"i":9,"n":"第九条","txt":"国家基准气候站、国家基本气象站、国家一般气象站和太阳辐射观测站周围的建筑物、作物、树木等障碍物和其他对气象探测有影响的各种源体，与气象观测场围栏必须保持一定距离，具体保护标准见附表1。 自动气象站四周不得有致使气象要素发生异常变化的干扰源。自动气象站具体保护标准根据其布设站类按照附表1执行。 生态气象监测站（含农业气象站）、酸雨监测站具体保护标准根据其布设站类参照附表1执行。 本办法所称源体，是指省级气象主管机构确定的对气象探测资料的代表性、准确性有影响的大型锅炉、废水、废气、垃圾场等干扰源或者其他源体。"},{"i":10,"n":"第十条","txt":"高空气象探测站四周的障碍物对探测系统天线形成的遮挡仰角不得大于5°，在高空气象探测站盛行风的下风方向120°范围内，不得大于2°。 在探测气球施放场地半径50米范围内，不得有架空电线、建筑物、树木等障碍物。其他建筑物和火源与氢气房的距离不得小于50米。"},{"i":11,"n":"第十一条","txt":"天气雷达站主要探测方向的遮挡仰角不得大于0.5°，孤立遮挡方位角不得大于0.5°；其他方向的遮挡仰角不得大于1°，孤立遮挡方位角不得大于1°，且总的遮挡方位角不得大于5°。 天气雷达站四周不得有对雷达接收产生干扰的干扰源。"},{"i":12,"n":"第十二条","txt":"气象卫星地面接收站（含静止气象卫星地面接收站、极轨气象卫星地面接收站）、卫星测控站、卫星测距站探测环境和设施的保护按照国家关于《地球站电磁环境保护要求》（GB13615—92）执行。 极轨气象卫星地面接收站周围障碍物的仰角不得大于3°。"},{"i":13,"n":"第十三条","txt":"大气本底台站的保护区划分为核心保护区、基本保护区、外围保护区，具体的保护范围和标准按照附表2执行。"},{"i":14,"n":"第十四条","txt":"沙尘暴监测站、污染气象监测站等环境气象监测站探测环境和设施保护标准由国务院气象主管机构另行制定。"},{"i":15,"n":"第十五条","txt":"严禁在遥感卫星辐射校正场场区内从事任何建设和改变场区内自然状态的行为。 本办法所称遥感卫星辐射校正场，是指利用辐射特性稳定、均匀的地物目标作为辐射参考基准，通过星地同步观测，对在轨运行遥感仪器进行绝对辐射定标或星上辐射定标校正的场地。"},{"i":16,"n":"第十六条","txt":"闪电探测站的高频探测天线60°下视角空间之内不得有任何障碍物。以闪电探测站的高频探测天线为中心，半径100米范围以内，不得有导电物体或者高于天线系统的障碍物。半径100米范围以外（含100米），障碍物与天线的仰角不得大于3°,电磁场干扰应当小于闪电接收机的阈值范围。"},{"i":17,"n":"第十七条","txt":"GPS气象探测站视场周围障碍物的仰角不得大于10°，且远离大功率的无线电发射台和高压输电线。各种无线电发射台与GPS气象探测站接收机天线的距离不得小于2公里，高压输电线与接收机天线的距离不得小于200米。 GPS气象探测站附近不得有大面积的水域或者其他对电磁波反射（吸收）强烈的物体。"},{"i":18,"n":"第十八条","txt":"各类无线电台(站)不得对气象专用频道、频率产生干扰。气象通信线路和设施不得被挤占、挪用、损坏，以保证气象信息及时、准确地传输。 气象无线电频率的保护，按照国家无线电管理法规执行。"},{"i":19,"n":"第十九条","txt":"各级气象主管机构应当将气象探测环境和设施保护的标准报送当地人民政府及其有关部门备案。"},{"i":20,"n":"第二十条","txt":"城乡规划、建设、国土等有关部门，在审批可能影响已建气象台站探测环境和设施的建设项目时，应当事先征得有审批权限的气象主管机构的同意。未经气象主管机构同意，有关部门不得审批。 新建、改建和扩建气象台站和设施，应当符合气象探测环境和设施的保护标准。"},{"i":21,"n":"第二十一条","txt":"未经依法批准，任何组织或者个人不得迁移气象台站和设施。确因实施城市规划或者国家重点工程建设，需要迁移国家基准气候站、国家基本气象站、高空气象探测站、天气雷达站、大气本底台站等国家布点的气象台站的，应当报经国务院气象主管机构批准；需要迁移其他气象台站的，应当报经省、自治区、直辖市气象主管机构批准。拆迁和新建气象台站和设施的全部费用由同级政府或者建设单位承担，并保证新建气象台站和设施的质量符合国家标准。 迁移的气象台站应当按照国务院气象主管机构的规定进行对比观测。"},{"i":22,"n":"第二十二条","txt":"无人值守的自动气象站，应当由该站的所有单位委托所在地人民政府或者社会团体、企事业单位和个人负责保护。当事人应当签订《委托保管书》，明确各自的权利和义务。"},{"i":23,"n":"第二十三条","txt":"禁止下列危害气象探测环境和设施的行为： (一)侵占、损毁和擅自移动气象台站建筑、设备和传输设施； (二)在气象探测环境保护范围内设置障碍物； (三)在气象探测环境保护范围内进行爆破、采砂（石）、取土、焚烧、放牧等行为； (四)在气象探测环境保护范围内种植影响气象探测环境和设施的作物、树木； (五)设置影响气象探测设施工作效能的高频电磁辐射装置； (六)进入气象台站实施影响气象探测工作的活动； (七)其他危害气象探测环境和设施的行为。"},{"i":24,"n":"第二十四条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构按照权限责令停止违法行为，限期恢复原状或者采取其他补救措施，可以并处5万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。 (一)侵占、损毁和擅自移动气象台站建筑、设备和传输设施的； (二)在气象探测环境保护范围内设置障碍物的； (三)设置影响气象探测设施工作效能的高频电磁辐射装置的； (四)其他危害气象探测环境和设施的行为。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构按照权限责令停止违法行为，限期恢复原状或者采取其他补救措施，可以并处3万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。 (一)在气象探测环境保护范围内进行爆破、采砂（石）、取土、焚烧、放牧等行为的； (二)在气象探测环境保护范围内种植影响气象探测环境和设施的作物、树木的； (三)进入气象台站实施影响气象探测工作的活动的。"},{"i":26,"n":"第二十六条","txt":"国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门所属的气象台站的探测环境和设施的保护标准，参照本办法执行。"},{"i":27,"n":"第二十七条","txt":"本办法所称大于、小于、高于，包括本数。"},{"i":28,"n":"第二十八条","txt":"本办法自2004年10月1日起施行。 附表:1.各类气象站气象观测场围栏与周围障碍物边缘和各种影响源体边缘之间距离的保护标准（略） 2.大气本底台站保护区划分和保护标准（略）"}],"qixiangzaihaiyujingxinhaofabuyuchuanbobanfa":[{"i":1,"n":"第一条","txt":"为了规范气象灾害预警信号发布与传播，防御和减轻气象灾害，保护国家和人民生命财产安全，依据《中华人民共和国气象法》、《国家突发公共事件总体应急预案》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域发布与传播气象灾害预警信号，必须遵守本办法。 本办法所称气象灾害预警信号（以下简称预警信号），是指各级气象主管机构所属的气象台站向社会公众发布的预警信息。 预警信号由名称、图标、标准和防御指南组成，分为台风、暴雨、暴雪、寒潮、大风、沙尘暴、高温、干旱、雷电、冰雹、霜冻、大雾、霾、道路结冰等。"},{"i":3,"n":"第三条","txt":"预警信号的级别依据气象灾害可能造成的危害程度、紧急程度和发展态势一般划分为四级：Ⅳ级（一般）、Ⅲ级（较重）、Ⅱ级（严重）、Ⅰ级（特别严重），依次用蓝色、黄色、橙色和红色表示，同时以中英文标识。 本办法根据不同种类气象灾害的特征、预警能力等，确定不同种类气象灾害的预警信号级别。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构负责全国预警信号发布、解除与传播的管理工作。 地方各级气象主管机构负责本行政区域内预警信号发布、解除与传播的管理工作。 其他有关部门按照职责配合气象主管机构做好预警信号发布与传播的有关工作。"},{"i":5,"n":"第五条","txt":"地方各级人民政府应当加强预警信号基础设施建设，建立畅通、有效的预警信息发布与传播渠道，扩大预警信息覆盖面，并组织有关部门建立气象灾害应急机制和系统。 学校、机场、港口、车站、高速公路、旅游景点等人口密集公共场所的管理单位应当设置或者利用电子显示装置及其他设施传播预警信号。"},{"i":6,"n":"第六条","txt":"国家依法保护预警信号专用传播设施，任何组织或者个人不得侵占、损毁或者擅自移动。"},{"i":7,"n":"第七条","txt":"预警信号实行统一发布制度。 各级气象主管机构所属的气象台站按照发布权限、业务流程发布预警信号，并指明气象灾害预警的区域。发布权限和业务流程由国务院气象主管机构另行制定。 其他任何组织或者个人不得向社会发布预警信号。"},{"i":8,"n":"第八条","txt":"各级气象主管机构所属的气象台站应当及时发布预警信号，并根据天气变化情况，及时更新或者解除预警信号，同时通报本级人民政府及有关部门、防灾减灾机构。 当同时出现或者预报可能出现多种气象灾害时，可以按照相对应的标准同时发布多种预警信号。"},{"i":9,"n":"第九条","txt":"各级气象主管机构所属的气象台站应当充分利用广播、电视、固定网、移动网、因特网、电子显示装置等手段及时向社会发布预警信号。在少数民族聚居区发布预警信号时除使用汉语言文字外，还应当使用当地通用的少数民族语言文字。"},{"i":10,"n":"第十条","txt":"广播、电视等媒体和固定网、移动网、因特网等通信网络应当配合气象主管机构及时传播预警信号，使用气象主管机构所属的气象台站直接提供的实时预警信号，并标明发布预警信号的气象台站的名称和发布时间，不得更改和删减预警信号的内容，不得拒绝传播气象灾害预警信号，不得传播虚假、过时的气象灾害预警信号。"},{"i":11,"n":"第十一条","txt":"地方各级人民政府及其有关部门在接到气象主管机构所属的气象台站提供的预警信号后，应当及时公告，向公众广泛传播，并按照职责采取有效措施做好气象灾害防御工作，避免或者减轻气象灾害。"},{"i":12,"n":"第十二条","txt":"气象主管机构应当组织气象灾害预警信号的教育宣传工作，编印预警信号宣传材料，普及气象防灾减灾知识，增强社会公众的防灾减灾意识，提高公众自救、互救能力。"},{"i":13,"n":"第十三条","txt":"违反本办法规定，侵占、损毁或者擅自移动预警信号专用传播设施的，由有关气象主管机构依照《中华人民共和国气象法》第三十五条的规定追究法律责任。"},{"i":14,"n":"第十四条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构依照《中华人民共和国气象法》第三十八条的规定追究法律责任： （一）非法向社会发布与传播预警信号的； （二）广播、电视等媒体和固定网、移动网、因特网等通信网络不使用气象主管机构所属的气象台站提供的实时预警信号的。"},{"i":15,"n":"第十五条","txt":"气象工作人员玩忽职守，导致预警信号的发布出现重大失误的，对直接责任人员和主要负责人给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"地方各级气象主管机构所属的气象台站发布预警信号，适用本办法所附《气象灾害预警信号及防御指南》中的各类预警信号标准。 省、自治区、直辖市制定地方性法规、地方政府规章或者规范性文件时，可以根据本行政区域内气象灾害的特点，选用或者增设本办法规定的预警信号种类，设置不同信号标准，并经国务院气象主管机构审查同意。"},{"i":17,"n":"第十七条","txt":"国务院气象主管机构所属的气象台站发布的预警信号标准由国务院气象主管机构另行制定。"},{"i":18,"n":"第十八条","txt":"本办法自发布之日起施行。 气象灾害预警信号及防御指南 一、台风预警信号 台风预警信号分四级，分别以蓝色、黄色、橙色和红色表示。 （一）台风蓝色预警信号 图标：（略） 标准： 24小时内可能或者已经受热带气旋影响，沿海或者陆地平均风力达6级以上，或者阵风8级以上并可能持续。防御指南： 1.政府及相关部门按照职责做好防台风准备工作； 2.停止露天集体活动和高空等户外危险作业； 3.相关水域水上作业和过往船舶采取积极的应对措施，如回港避风或者绕道航行等； 4.加固门窗、围板、棚架、广告牌等易被风吹动的搭建物，切断危险的室外电源。 （二）台风黄色预警信号 图标：（略） 标准：24小时内可能或者已经受热带气旋影响，沿海或者陆地平均风力达8级以上，或者阵风10级以上并可能持续。 防御指南： 1.政府及相关部门按照职责做好防台风应急准备工作； 2.停止室内外大型集会和高空等户外危险作业； 3.相关水"}],"qixianghangyeguanliruoganguiding":[{"i":1,"n":"第一条","txt":"为了加强气象行业管理，促进气象行业协调发展，优化资源配置，实现资源共享，提高气象行业的总体效益，依据《中华人民共和国气象法》，结合气象行业实际，制定本规定。"},{"i":2,"n":"第二条","txt":"各级气象主管机构及其所属的气象台站、国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门及其所属的气象台站等以及其他组织和个人，在中华人民共和国领域和中华人民共和国管辖的其他海域从事气象活动，应当遵守本规定。"},{"i":3,"n":"第三条","txt":"国务院气象主管机构负责全国气象行业管理工作。 地方各级气象主管机构在上级气象主管机构和本级人民政府的领导下，负责本行政区域内的气象行业管理工作。"},{"i":4,"n":"第四条","txt":"各级气象主管机构应当组织制定气象行业规划和政策，完善气象行业法规和标准，强化气象行业监督，加强气象行业协调、指导和服务，合理配置国家对气象行业的投入。"},{"i":5,"n":"第五条","txt":"各级气象主管机构应当组织开展气象行业的业务和科技合作与交流、气象科普宣传、气象科技成果推广等活动，提高气象工作水平。"},{"i":6,"n":"第六条","txt":"国务院气象主管机构和省、自治区、直辖市气象主管机构应当按照合理布局、有效利用、兼顾当前与长远需要的原则编制气象事业发展规划。 全国气象事业发展规划，由国务院气象主管机构组织有关部门编制，报国务院或者有关部门批准后组织实施。 省、自治区、直辖市的气象事业发展规划，由省、自治区、直辖市气象主管机构根据全国气象事业发展规划，组织有关部门编制，经国务院气象主管机构和本级人民政府批准后实施。 国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门，可以参考气象事业发展规划，结合本部门的业务实际，制定本部门或者本系统的气象事业发展规划，报国务院气象主管机构备案后，组织实施。"},{"i":7,"n":"第七条","txt":"重要气象设施建设项目应当符合重要气象设施建设规划要求，并在项目建议书和可行性研究报告批准前，征求国务院气象主管机构或者省、自治区、直辖市气象主管机构的意见。"},{"i":8,"n":"第八条","txt":"各级气象主管机构新建气象台站，应当按照审批权限，经国务院气象主管机构或者省、自治区、直辖市气象主管机构批准后方可建立。建设时，必须遵守气象台站的建设标准和规范。 国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门以及其他组织和个人新建气象台站，应当执行气象台站建设的有关规定和标准、规范，投入运行后3个月内应当报当地省、自治区、直辖市气象主管机构备案。 为教学、科学研究、科普等开展的临时气象观测，投入运行后3个月内应当报当地省、自治区、直辖市气象主管机构备案。"},{"i":9,"n":"第九条","txt":"各级气象主管机构迁移气象台站的，应当按照《气象设施和气象探测环境保护条例》第十八条的规定执行。 国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门迁移、撤销本部门或者本系统气象台站的，迁移、撤销后3个月内应当报当地省、自治区、直辖市气象主管机构备案。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市气象主管机构对本行政区域内的国务院其他有关部门或者省、自治区、直辖市人民政府其他有关部门以及其他组织和个人建设的气象台站情况，应当定期进行备案统计。"},{"i":11,"n":"第十一条","txt":"国务院气象主管机构负责全国气象标准化工作的归口管理，统一组织制定、修订气象国家标准和行业标准、规范和规程。 省、自治区、直辖市气象主管机构可以根据需要，组织有关部门制定、修订气象地方标准、规范和规程。"},{"i":12,"n":"第十二条","txt":"各级气象主管机构、国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门应当组织气象标准、规范和规程的实施，其所属的气象台站应当遵守国家制定的气象标准、规范和规程。有特殊规定的，从其规定。"},{"i":13,"n":"第十三条","txt":"国务院气象主管机构和省、自治区、直辖市气象主管机构应当加强气象信息网络系统建设，建立气象信息共享、共用平台，实现气象信息资源共享。 国务院气象主管机构和省、自治区、直辖市气象主管机构应当做好汇交气象资料的接收、保存、应用和监管工作。"},{"i":14,"n":"第十四条","txt":"各级气象主管机构所属的气象台站，应当按照国务院气象主管机构的规定，进行气象探测并向有关气象主管机构汇交气象探测资料。未经上级气象主管机构批准，不得中止气象探测。 国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门所属的气象台站及其他从事气象探测的组织和个人，应当按照国家有关规定向国务院气象主管机构或者省、自治区、直辖市气象主管机构汇交所获得的气象探测资料。"},{"i":15,"n":"第十五条","txt":"参加汇交、共享的气象探测资料，应当符合国家制定的相关标准、规范、规程和国务院气象主管机构的有关要求。 具有大气环境影响评价资质的单位进行工程建设项目大气环境影响评价时，应当使用符合国家气象技术标准的气象资料。"},{"i":16,"n":"第十六条","txt":"各级气象主管机构所属的气象台站应当按照职责向社会发布公众气象预报、灾害性天气警报和气象灾害预警信号，并根据天气变化情况及时补充或者订正。其他任何组织或者个人不得向社会发布公众气象预报、灾害性天气警报和气象灾害预警信号。 国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门所属的气象台站，可以发布供本系统使用的专项气象预报，但不得以任何形式向社会公开发布。 各级气象主管机构应当加强对国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门所属的气象台站预报业务和服务工作的指导，提高其业务水平和服务能力。"},{"i":17,"n":"第十七条","txt":"气象台站应当使用标有质量标识，并由国务院气象主管机构颁发使用许可证的气象专用技术装备。 未经检定、检定不合格或者超过检定有效期的气象计量器具不得在气象业务中使用。"},{"i":18,"n":"第十八条","txt":"国务院气象主管机构或者省、自治区、直辖市气象主管机构应当根据气象事业发展需要，会同有关部门，提出气象行业专业技术人员定期培训要求，制定业务技术培训计划，并组织实施。"},{"i":19,"n":"第十九条","txt":"外国组织和个人在中华人民共和国领域及其管辖的其他海域单独或者合作从事气象活动，应当经国务院气象主管机构会同有关部门批准。 台湾、香港、澳门地区的组织和个人在中华人民共和国领域及其管辖的其他海域单独或者合作从事气象活动，参照本规定执行。"},{"i":20,"n":"第二十条","txt":"各级气象主管机构应当会同有关部门定期组织对气象台站执行气象标准、规范、规程等情况的监督检查，对不符合规定的，限期改正。"},{"i":21,"n":"第二十一条","txt":"重要气象设施建设项目不符合重要气象设施建设规划要求，未在项目建议书和可行性研究报告批准前，征求国务院气象主管机构或者省、自治区、直辖市气象主管机构的意见的，由当地气象主管机构报请本级人民政府责令改正；造成重大损失的，由当地人民政府依法追究有关责任人的行政责任。"},{"i":22,"n":"第二十二条","txt":"违反本规定，有下列行为之一的，由有关气象主管机构按照权限依法提请当地人民政府或者上级主管部门责令其限期改正，情节严重的给予警告： （一）未遵守国家制定的气象标准、规范、规程的； （二）逾期未向当地省、自治区、直辖市气象主管机构备案的。"},{"i":23,"n":"第二十三条","txt":"本规定未作规范的，按照《中华人民共和国气象法》以及其他法律、法规、规章规定执行。"},{"i":24,"n":"第二十四条","txt":"中华人民共和国缔结或者参加的有关气象活动的国际条约与本规定有不同规定的，适用该国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":25,"n":"第二十五条","txt":"本规定自2017年5月1日起施行。2005年12月6日公布的中国气象局第12号令《气象行业管理若干规定》同时废止。"}],"qixiangxingzhengfuyibanfa":[{"i":1,"n":"第一条","txt":"为了防止和纠正违法或者不当的具体行政行为，保护公民、法人和其他组织的合法权益，保障和监督气象主管机构依法行使职权，根据《中华人民共和国行政复议法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为气象主管机构作出的具体行政行为侵犯其合法权益，向气象主管机构申请行政复议，气象主管机构受理行政复议申请，并作出气象行政复议决定，适用本办法。"},{"i":3,"n":"第三条","txt":"气象主管机构负责法制工作的机构(以下简称气象法制机构)具体负责气象行政复议工作，并履行下列职责： (一)受理行政复议申请； (二)向有关组织和人员调查取证，查阅文件和资料； (三)审查申请行政复议的具体行政行为是否合法与适当，拟订气象行政复议决定； (四)处理或者转送本办法第五条规定的审查申请； (五)对气象主管机构违反本办法规定的行为，依照规定的权限和程序提出处理建议； (六)办理因不服行政复议决定提起行政诉讼的应诉事项； (七)法律、法规规定的其他职责。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织对气象主管机构作出的下列具体行政行为不服的，可以申请行政复议： (一)对气象主管机构作出的警告、罚款、暂扣或者吊销许可证(资质证、资格证)等行政处罚决定不服的； (二)认为符合法定条件，申请气象主管机构办理的许可证(资质证、资格证)等行政许可手续，气象主管机构拒绝办理或者在法定期限内没有依法办理的； (三)对气象主管机构作出的有关许可证(资质证、资格证)等变更、中止、取消的决定不服的； (四)认为符合法定条件，申请气象主管机构审批、审核、登记等有关事项，气象主管机构没有依法办理的； (五)认为气象主管机构作出的其他具体行政行为侵犯其合法权益的。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织认为气象主管机构的具体行政行为所依据的除法律、法规、规章和国务院文件以外的其他规范性文件不合法的，在对具体行政行为向气象行政复议机构提出行政复议申请时，可以一并申请对规范性文件的审查。"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织对下列事项，不能申请行政复议： (一)对鉴定部门作出的鉴定结论不服的； (二)向人民法院提起行政诉讼，人民法院已经依法受理的； (三)法律、法规规定的其他情形。"},{"i":7,"n":"第七条","txt":"对县级以上气象主管机构的具体行政行为不服的，可以向上一级气象主管机构申请行政复议，也可以按照《中华人民共和国行政复议法》第十二条的规定向本级人民政府申请行政复议。"},{"i":8,"n":"第八条","txt":"对依法受委托的属于事业组织等作出的具体行政行为不服的，可以向委托的气象主管机构的上一级气象主管机构申请行政复议，也可以按照《中华人民共和国行政复议法》第十二条的规定向本级人民政府申请行政复议。委托的气象主管机构是被申请人。"},{"i":9,"n":"第九条","txt":"对气象主管机构和政府其他部门以共同名义作出的具体行政行为不服的，可以向其共同的上一级行政机关申请复议。共同作出具体行政行为的气象主管机构是共同被申请人之一。"},{"i":10,"n":"第十条","txt":"对依法需要上级气象主管机构批准的具体行政行为不服申请的行政复议，由批准的气象主管机构管辖。"},{"i":11,"n":"第十一条","txt":"对国务院气象主管机构的具体行政行为不服的，向国务院气象主管机构申请行政复议。对气象行政复议决定不服的，可以向人民法院提出行政诉讼；也可以按照《中华人民共和国行政复议法》第十四条的规定向国务院申请裁决。"},{"i":12,"n":"第十二条","txt":"公民、法人或者其他组织认为具体行政行为侵犯其合法权益的，可以自知道该具体行为之日起60日内，向行政复议机构提出行政复议申请。 因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。"},{"i":13,"n":"第十三条","txt":"依照本办法申请行政复议的公民、法人或者其他组织是气象行政复议的申请人。 有权申请行政复议的公民死亡的，其近亲属可以申请气象行政复议。有权申请行政复议的公民是无行为能力人或者限制行为能力人，其法定代理人可以代为申请行政复议。有权申请行政复议的法人或者其他组织终止的，承受其权利的法人或者其他组织可以申请气象行政复议。 同申请行政复议的具体行政行为有利害关系的其他公民、法人或者其他组织，可以作为第三人参加气象行政复议。"},{"i":14,"n":"第十四条","txt":"公民、法人或者其他组织对气象主管机构作出的具体行政行为不服申请行政复议的，作出具体行政行为的气象主管机构是被申请人；对由上级气象主管机构批准的具体行政行为不服申请行政复议的，作出具体行政行为的气象主管机构是被申请人。"},{"i":15,"n":"第十五条","txt":"申请人申请行政复议，可以采取书面申请，也可以采取口头申请。 对口头申请的，气象行政复议机构应当当场记录申请人的基本情况、行政复议请求、申请行政复议的主要事实、理由和时间。"},{"i":16,"n":"第十六条","txt":"气象行政复议机构收到行政复议申请后，应当注明收到日期，在5日内进行审查，并按照下列情况分别作出决定： (一)对符合法定受理条件，并属于本机关受理范围的，作出受理决定； (二)对符合法定受理条件，但不属于本机关受理范围的，应当书面告知申请人向有关机关提出申请； (三)对不符合法定受理条件的，应当自收到该行为复议申请的7日内作出不予受理决定，并制作《行政复议不予受理决定书》，送达申请人，该决定书中应当说明不予受理的理由。"},{"i":17,"n":"第十七条","txt":"气象行政复议机构以外的其他职能机构收到气象行政复议申请的，应当及时将其转送气象行政复议机构。 气象行政复议机构收到气象行政复议申请书之日起即为受理。"},{"i":18,"n":"第十八条","txt":"申请人认为气象行政复议机构无正当理由不受理其复议申请的，可以向上级气象主管机构反映，上级气象主管机构在审查后认为申请人提出的申请符合法定受理条件的，应当责令下级气象主管机构予以受理；必要时，上级气象主管机构也可以直接受理。"},{"i":19,"n":"第十九条","txt":"气象行政复议机构受理气象行政复议申请后，可以与本级气象主管机构的其他有关职能机构共同对气象行政复议案件进行审查。"},{"i":20,"n":"第二十条","txt":"气象行政复议案件原则上采取书面审查的办法，但是申请人提出要求或者气象行政复议机构认为有必要时，可以向有关组织和人员调查情况，听取申请人、被申请人和第三人的意见。"},{"i":21,"n":"第二十一条","txt":"气象行政复议机构应当自气象行政复议申请受理之日起7日内，将气象行政复议申请书副本或者气象行政复议申请笔录的复印件送被申请人。被申请人应当自收到申请书副本或者申请笔录复印件之日起10日内，提出书面答复，并提交作出具体行政行为的证据、依据和其他有关材料。 申请人、第三人可以查阅被申请人提出的书面答复、作出具体行政行为的证据、依据和其他有关材料，除涉及国家秘密、商业秘密或者个人隐私外，气象行政复议机构不得拒绝。"},{"i":22,"n":"第二十二条","txt":"在气象行政复议过程中，被申请人不得自行向申请人和其他有关组织或者个人收集证据。"},{"i":23,"n":"第二十三条","txt":"气象行政复议决定作出前，申请人要求撤回气象行政复议的，经说明理由，可以撤回；撤回气象行政复议申请的，行政复议终止。"},{"i":24,"n":"第二十四条","txt":"气象行政复议机构在审查申请人对本办法第五条规定的作出具体行政行为所依据的规范性文件合法性时，应当根据具体情况，分别作出以下处理： (一)本级气象主管机构有权处理的，应当在30日内对该规定依法作出处理； (二)本级气象主管机构无权处理的，应当在7日内按照法定程序转送有处理权的气象主管机构或者其他国家机关处理。 对该规定进行审查期间，中止对具体行政行为的审查。审查结束后，气象行政复议机构再继续本案具体行政行为的审查。中止审查期间，应当将有关中止的情况通知申请人和被申请人。"},{"i":25,"n":"第二十五条","txt":"气象行政复议机构对被申请人作出的具体行政行为在进行审查时，认为其作出的具体行政行为的依据不合法的，本机关应当在30日内依法作出处理；无权处理的，应当在7日内按照法定程序移交有处理权的国家机关依法处理。处理期间，中止对具体行政行为的审查。"},{"i":26,"n":"第二十六条","txt":"气象行政复议机构应当对被申请人作出的具体行政行为进行全面审查，并提出处理意见。经气象主管机构负责人审查同意后，分别按照下列规定作出行政复议决定： (一)具体行政行为认定事实清楚，证据确凿，适用法律、法规依据正确，程序合法和内容适当的，决定维持原具体行政行为； (二)被申请人不履行法律、法规规定的职责的，决定其在15日内履行； (三)被申请人的具体行政行为有下列行为之一的，决定撤销、变更或者确认该具体行政行为违法，并可以责令被申请人对决定撤销或者确认违法的具体行政行为在60日内重新作出具体行政行为： 1.主要事实不清、证据不足的； 2.适用依据错误的； 3.违反法定程序的； 4.超越或者滥用职权的； 5.具体行政行为明显不当的。 (四)被申请人未按规定提出书面答复、提交当初作出具体行政行为的证据、依据和其他有关材料的，视为该具体行政行为没有证据、依据，决定撤销该具体行政行为。 气象行政复"},{"i":27,"n":"第二十七条","txt":"气象行政复议机构作出的行政复议决定，应当制作《行政复议决定书》。 《行政复议决定书》应当载明下列事项： (一)申请人的姓名、性别、年龄、工作单位、住址(法人或者其他组织的名称、地址、法定代表人的姓名、职务)； (二)被申请人的名称、地址、法定代表人的姓名、职务； (三)申请人的复议请求和理由； (四)气象行政复议机构认定的事实、理由，适用的法律、法规、规章及其他规范性文件； (五)复议结论； (六)申请人不服复议决定向人民法院起诉的期限； (七)作出复议决定的年、月、日。 气象行政复议决定书应当加盖本级气象主管机构的印章。"},{"i":28,"n":"第二十八条","txt":"气象行政复议机构应当自受理申请之日起60日内作出行政复议决定。情况复杂，不能在规定的期限内作出行政复议决定的，经同级气象主管机构的负责人同意，可以适当延长，但最多不超过30日。"},{"i":29,"n":"第二十九条","txt":"气象行政复议机构应当根据《中华人民共和国民事诉讼法》的规定，采用直接送达、邮寄送达或者委托送达等方式，将气象行政复议决定书送达申请人和被申请人。"},{"i":30,"n":"第三十条","txt":"申请人对气象行政复议决定不服的，可以在收到《行政复议决定书》之日起15日内，向人民法院起诉。逾期不起诉又不履行的，由气象主管机构申请人民法院强制执行或者依法强制执行。"},{"i":31,"n":"第三十一条","txt":"气象行政复议案件审查结束后，应当将案件的材料立卷归档。 对有重大影响的气象行政复议案件，结案后应当将结案报告，报国务院气象主管机构。"},{"i":32,"n":"第三十二条","txt":"上级气象主管机构应当加强对下级气象主管机构气象行政复议工作的指导和监督，发现下级气象主管机构在气象行政复议工作中确有错误的，有权责令其改正，下级气象主管机构必须执行。"},{"i":33,"n":"第三十三条","txt":"气象行政复议机构受理行政复议申请，不得向申请人收取任何费用。气象行政复议活动所需经费，应当按照《中华人民共和国行政复议法》第三十九条的规定，列入本机关的行政经费中，由本级财政予以保障。"},{"i":34,"n":"第三十四条","txt":"计划单列市气象主管机构从事气象行政复议的权限，按照地(市)气象主管机构的权限执行。"},{"i":35,"n":"第三十五条","txt":"气象行政复议机构审理复议案件，应当使用国务院法制工作办公室制作的，由国务院气象主管机构统一印制的行政复议法律文书。"},{"i":36,"n":"第三十六条","txt":"本办法未作规定的事项，遵照《中华人民共和国行政复议法》的有关规定执行。"},{"i":37,"n":"第三十七条","txt":"本办法由国务院气象主管机构负责解释。"},{"i":38,"n":"第三十八条","txt":"本办法自发布之日起施行。"}],"qixiangxingzhengguifanxingwenjianguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强气象行政规范性文件的管理，规范气象行政规范性文件的制定、审核和备案等活动，提高气象行政规范性文件的质量，实现与有关法律法规相衔接，促进气象依法行政，根据有关法律、法规规定，结合气象部门实际，制定本办法。"},{"i":2,"n":"第二条","txt":"气象行政规范性文件的制定、审核、备案、清理以及相关的监督管理工作，适用本办法。 本办法所称气象行政规范性文件是指除部门规章外，由县级以上气象主管机构依照法定权限、程序制定并公开发布，涉及公民、法人和其他组织权利义务，具有普遍约束力，在一定期限内反复适用的公文。 气象主管机构内部执行的管理规范、工作制度、机构编制、会议纪要、工作方案、请示报告及表彰奖惩、人事任免等文件，不适用本办法。"},{"i":3,"n":"第三条","txt":"气象行政规范性文件管理应当遵循以下原则： （一）保证宪法、法律、法规、规章的正确实施； （二）维护国家法制统一和政令统一； （三）保障公民、法人和其他组织的合法权益； （四）坚持公开、公众参与； （五）坚持程序完备、权责一致、相互衔接、运行高效。"},{"i":4,"n":"第四条","txt":"气象行政规范性文件规定的事项应当属于执行法律、法规、规章和上级行政规范性文件的规定，且需要制定行政规范性文件的事项。 气象行政规范性文件应当依照法定职责权限、程序制定。不得增加法律、法规规定之外的行政权力事项或者减少法定职责；不得设定行政许可、行政处罚、行政强制、行政征收、行政收费等事项；不得增加办理行政许可事项的条件，规定出具循环证明、重复证明、无谓证明的内容；不得违法制定含有排除或者限制公平竞争内容的措施；不得违法减损公民、法人和其他组织的合法权益或者增加其义务。"},{"i":5,"n":"第五条","txt":"县级以上气象主管机构可以在其职权范围内制定气象行政规范性文件。不得以部门内设机构、临时机构和议事协调机构等名义制发气象行政规范性文件。"},{"i":6,"n":"第六条","txt":"气象行政规范性文件可以称“办法”“规定”“规程”“细则”和“规则”等名称，不得称“法”或者“条例”。"},{"i":7,"n":"第七条","txt":"县级以上气象主管机构组织起草气象行政规范性文件时，可以确定一个或者几个内设机构具体负责起草（以下简称起草机构）。"},{"i":8,"n":"第八条","txt":"起草气象行政规范性文件，应当对文件制发的必要性、可行性和拟解决的主要问题等进行调查研究。 起草气象行政规范性文件，应当对拟设定的主要制度和措施的预期效果以及可能产生的影响进行评估。 对专业性、技术性较强的气象行政规范性文件，应当组织相关领域专家进行论证。 评估论证结论应当在文件起草说明中写明，作为制发文件的重要依据。"},{"i":9,"n":"第九条","txt":"除依法不得公开的事项外，气象行政规范性文件在起草过程中应当公开征求意见。 对涉及群众重大利益调整的，可以采取召开座谈会、论证会、实地走访等形式充分听取各方面意见，重点听取利益相关方的意见。 征求意见应当公布文件草案及其说明等材料，并明确提出意见的方式和期限，可以通过门户网站等便于公众知晓的方式开展。气象行政规范性文件征求意见的期限一般不少于十五日。"},{"i":10,"n":"第十条","txt":"县级以上气象主管机构制定气象行政规范性文件，应当依照本办法的规定进行合法性审核。与其他部门联合制定行政规范性文件，应当分别就其职责事项进行合法性审核。 未经合法性审核的或者经审核不合法的气象行政规范性文件，不得提交本级气象主管机构审议。"},{"i":11,"n":"第十一条","txt":"合法性审核应当由承担法制工作的机构（以下简称合法性审核机构）负责。 国务院气象主管机构和省、自治区、直辖市气象主管机构的法制工作机构负责对本级制定的气象行政规范性文件进行合法性审核。 地（市）级气象主管机构的法制工作机构负责对本级和下级气象主管机构制定的气象行政规范性文件进行合法性审核。"},{"i":12,"n":"第十二条","txt":"起草机构在形成气象行政规范性文件送审稿后，应当由本级气象主管机构的办公机构审核后再进行合法性审核。"},{"i":13,"n":"第十三条","txt":"起草机构应当向办公机构提交下列材料： （一）气象行政规范性文件的送审稿； （二）气象行政规范性文件的起草说明（包括制定依据、必要性与可行性、需要解决的问题、拟规定的主要制度和拟采取的主要措施，起草过程、所采取措施预期效果和影响的评估论证结论、征求意见及采纳情况等内容）； （三）其他有关材料。"},{"i":14,"n":"第十四条","txt":"办公机构应当对起草机构是否严格依照规定的程序起草、是否进行评估论证、是否广泛征求意见等进行审核并出具审核意见。 经审核，符合要求的，办公机构出具审核意见并转送合法性审核机构进行审核；不符合要求的，可以退回，或者要求起草机构在规定时间内补充材料或者说明情况后转送合法性审核机构进行审核。"},{"i":15,"n":"第十五条","txt":"合法性审核机构应当对材料的完备性、规范性进行审核，不符合要求的，可以退回，或者要求起草单位在规定时间内补充材料或者说明情况。 合法性审核内容包括： （一）制定主体是否合法； （二）是否超越气象主管机构的法定职权； （三）内容是否符合宪法、法律、法规、规章和国家政策规定； （四）是否违法设立行政许可、行政处罚、行政强制、行政征收、行政收费等事项； （五）是否增加办理行政许可事项的条件； （六）是否存在没有法律、法规依据作出减损公民、法人和其他组织合法权益或者增加其义务的情形； （七）是否存在没有法律、法规依据作出增加本单位权力或者减少本单位法定职责的情形； （八）是否违反行政规范性文件制定程序。"},{"i":16,"n":"第十六条","txt":"合法性审核机构对气象行政规范性文件进行审核时，根据不同情况提出书面审核意见。 认为不存在合法性问题的，提出“符合有关法律规定”的审核意见； 认为存在合法性问题的，对发现的问题按照下列情况提出审核意见： （一）制定主体不合法、超越职权、主要内容违法，提出“不符合有关法律规定”的审核意见； （二）程序不符合要求的，建议起草机构补正程序； （三）具体条文涉及本办法第四条第二款规定的，建议起草机构修改相关内容。"},{"i":17,"n":"第十七条","txt":"起草机构应当根据合法性审核意见对气象行政规范性文件作必要的修改或者补充；特殊情况下，起草机构未完全采纳合法性审核意见的，应当在提请本级气象主管机构审议时详细说明理由和依据。"},{"i":18,"n":"第十八条","txt":"除为了预防、应对和处置突发事件，或者执行上级机关的紧急命令和决定需要立即制定实施规范性文件等外，合法性审核机构应当自收到送审稿之日起审核，审核时间一般不少于五个工作日，最长不超过十五个工作日。"},{"i":19,"n":"第十九条","txt":"气象行政规范性文件应当由本级气象主管机构的办公会议集体审议，通过后由主要负责人签发。"},{"i":20,"n":"第二十条","txt":"气象行政规范性文件应当由办公机构进行统一登记、统一编号、统一印发，并及时通过政府信息公开渠道向社会发布，未经公布的不得作为行政管理的依据。 对涉及群众切身利益、社会关注度高的气象行政规范性文件，起草机构要做好文件解读工作。"},{"i":21,"n":"第二十一条","txt":"气象行政规范性文件应当载明施行日期。涉及的内容属于阶段性工作的，应当载明有效期。"},{"i":22,"n":"第二十二条","txt":"地方各级气象主管机构应当自气象行政规范性文件发布之日起三十日内，向上一级气象主管机构报送备案，同时抄送同级人民政府。"},{"i":23,"n":"第二十三条","txt":"报送气象行政规范性文件备案，应当提交气象行政规范性文件备案报告、正式文本（含起草说明），并同时提交该气象行政规范性文件的合法性审核意见。 备案报告应注明文件名称、文号、发文日期和发布方式，并加盖制定单位印章。"},{"i":24,"n":"第二十四条","txt":"接受备案的气象主管机构（以下简称备案机构）应当依照本办法第十五条的规定，对报送备案的气象行政规范性文件进行审查。"},{"i":25,"n":"第二十五条","txt":"备案机构发现气象行政规范性文件与法律、法规、规章和上级行政规范性文件相抵触，或者超越法定权限、违反制定程序的，应当及时通知气象主管机构停止执行、限期纠正；必要时，备案机构依照职权直接予以撤销或者改变。 气象主管机构收到备案机构的书面审查意见后，应当在十五个工作日内书面回复处理结果。对审查意见有异议的，可以申请复核。备案机构应当在收到复核申请之日起十五个工作日内书面回复意见。"},{"i":26,"n":"第二十六条","txt":"地方各级气象主管机构不按照规定报送备案的，由备案机构通知限期改正。 地方各级气象主管机构拖延不报送备案，或者对备案机构的审查意见不予纠正的，由备案机构给予通报批评；情节严重或者造成严重不良后果的，对直接负责的主管人员和其他直接责任人员依法追究责任。"},{"i":27,"n":"第二十七条","txt":"公民、法人或者其他组织对气象行政规范性文件有异议的，可以向气象主管机构、备案机构提出书面审查建议。 气象主管机构、备案机构应当在收到公民、法人或者其他组织提出书面审查建议之日起六十日内研究处理，并书面答复当事人；情况复杂的，经机构负责人批准，可以适当延长办理期限，但延长期限不得超过三十日，并应当告知当事人延期理由。法律、行政法规另有规定的，从其规定。"},{"i":28,"n":"第二十八条","txt":"公民、法人和其他组织在申请行政复议时一并提出对有关气象行政规范性文件的审查申请，或者行政复议机构在审查具体行政行为时认为其依据的气象行政规范性文件不合法的，依照《中华人民共和国行政复议法》的有关规定执行。"},{"i":29,"n":"第二十九条","txt":"气象主管机构应当适时组织对气象行政规范性文件的实施情况进行评估。认为气象行政规范性文件不应继续执行的，应当及时修改或者废止。 载明有效期的气象行政规范性文件，气象主管机构认为需要继续执行的，应当按照本办法规定重新公布，并自公布之日起重新计算有效期。"},{"i":30,"n":"第三十条","txt":"气象主管机构应当按照国家有关规定及时组织清理本机构制定的气象行政规范性文件；法律、法规另有规定的，从其规定。 气象行政规范性文件主要内容或者主要措施不符合法律、法规、规章和上级行政规范性文件规定的，气象主管机构应当废止。 气象行政规范性文件部分内容与现行有效的法律、法规、规章和上级行政规范性文件规定不符，但该文件又有必要继续执行的，气象主管机构应当进行修改。"},{"i":31,"n":"第三十一条","txt":"气象行政规范性文件进行清理后，气象主管机构应当及时向社会公布继续有效、废止和失效的气象行政规范性文件目录。"},{"i":32,"n":"第三十二条","txt":"地方政府规章对行政规范性文件制定和监督管理另有规定的，可以参照执行。"},{"i":33,"n":"第三十三条","txt":"本办法自2021年1月1日起施行。2011年9月30日公布的中国气象局第23号令《气象规范性文件管理办法》同时废止。"}],"qixiangxingzhengxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范气象行政许可行为，保护公民、法人和其他组织的合法权益，保障和监督气象主管机构有效实施行政管理，根据《中华人民共和国行政许可法》、《中华人民共和国气象法》、《人工影响天气管理条例》、《通用航空飞行管制条例》、《气象灾害防御条例》、《气象设施和气象探测环境保护条例》等有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称气象行政许可，是指县级以上气象主管机构根据公民、法人或者其他组织的申请，经依法审查，准予其从事特定活动的行为。"},{"i":3,"n":"第三条","txt":"实施气象行政许可，适用本办法。"},{"i":4,"n":"第四条","txt":"实施气象行政许可，遵循公开、公平、公正的原则。 气象行政许可的规定、技术标准和技术规范应当公布；未经公布的，不得作为实施气象行政许可的依据。气象行政许可的实施和结果，除涉及国家秘密、商业秘密或者个人隐私的外，应当公开。 符合法定条件、标准的，申请人有依法取得气象行政许可的权利。"},{"i":5,"n":"第五条","txt":"实施气象行政许可，应当遵循便民、高效原则，提供优质服务，提高办事效率。"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织对气象主管机构实施的气象行政许可，享有陈述权、申辩权；有权依法申请行政复议或者提起行政诉讼；其合法权益受到损害的，有权依法要求赔偿。"},{"i":7,"n":"第七条","txt":"依法取得的行政许可，除法律、法规规定依照法定条件和程序可以转让的外，不得转让。 被许可人不得涂改、伪造、倒卖、出租、出借气象行政许可证件或者以其他形式非法转让气象行政许可。"},{"i":8,"n":"第八条","txt":"气象主管机构实施气象行政许可，不得在法定条件之外附加其他条件，不得向申请人提出购买指定产品、接受有偿服务等不正当要求。 气象主管机构及其工作人员办理气象行政许可或者实施监督检查，不得索取或者收受申请人财物，不得谋取其他利益。"},{"i":9,"n":"第九条","txt":"气象行政许可由县级以上气象主管机构依照法定的权限、条件和程序在法定职权范围内实施。"},{"i":10,"n":"第十条","txt":"下列气象行政许可项目由国务院气象主管机构实施： （一）大气本底站、国家基准气候站、国家基本气象站迁建审批； （二）气象专用技术装备（含人工影响天气作业设备）使用审批； （三）外国组织和个人在华从事气象活动审批； （四）法律、行政法规规定的由国务院气象主管机构实施的其他气象行政许可项目。 电力、通信防雷装置检测单位资质认定由国务院气象主管机构和国务院电力或者国务院通信主管部门共同认定。"},{"i":11,"n":"第十一条","txt":"下列气象行政许可项目由省、自治区、直辖市气象主管机构实施： （一）除电力、通信以外的防雷装置检测单位资质认定； （二）升放无人驾驶自由气球、系留气球单位资质认定； （三）防雷装置设计审核和竣工验收； （四）新建、扩建、改建建设工程避免危害气象探测环境审批； （五）除大气本底站、国家基准气候站、国家基本气象站以外的气象台站迁建审批； （六）升放无人驾驶自由气球或者系留气球活动审批； （七）法律、法规、地方政府规章规定的由省、自治区、直辖市气象主管机构实施的其他气象行政许可项目。"},{"i":12,"n":"第十二条","txt":"下列气象行政许可项目由设区的市级气象主管机构实施： （一）防雷装置设计审核和竣工验收； （二）升放无人驾驶自由气球、系留气球单位资质认定； （三）升放无人驾驶自由气球或者系留气球活动审批； （四）法律、法规、地方政府规章规定的由设区的市级气象主管机构实施的其他气象行政许可项目。"},{"i":13,"n":"第十三条","txt":"下列气象行政许可项目由县级气象主管机构实施： （一）防雷装置设计审核和竣工验收； （二）升放无人驾驶自由气球或者系留气球活动审批； （三）法律、法规、地方政府规章规定的由县级气象主管机构实施的其他气象行政许可项目。"},{"i":14,"n":"第十四条","txt":"防雷装置设计审核和竣工验收，升放无人驾驶自由气球、系留气球单位资质认定，升放无人驾驶自由气球或者系留气球活动审批等气象行政许可项目的审批权限，由省、自治区、直辖市气象主管机构在法定权限内确定。"},{"i":15,"n":"第十五条","txt":"公民、法人或者其他组织从事特定活动，依法需要取得气象行政许可的，应当向有关气象主管机构提出申请。申请书需要采用格式文本的，气象主管机构应当向申请人提供气象行政许可申请书格式文本。申请书格式文本中不得包含与申请气象行政许可事项没有直接关系的内容。 申请人可以委托代理人提出气象行政许可申请，委托代理人提出气象行政许可申请的，应当提交授权委托书。授权委托书应当载明授权委托事项、授权范围和时限。"},{"i":16,"n":"第十六条","txt":"建立气象行政许可服务窗口的气象主管机构，由该服务窗口负责统一受理气象行政许可申请，统一送达气象行政许可决定；没有建立服务窗口的，应当由该气象主管机构确定的机构设立专门岗位负责统一受理气象行政许可申请，统一送达气象行政许可决定。"},{"i":17,"n":"第十七条","txt":"气象主管机构应当将法律、法规、规章规定的有关气象行政许可的事项、依据、条件、数量、程序、期限以及需要提交的全部材料的目录和申请书示范文本等信息通过网站或者其他方式向社会公开，便于申请人查询和办理。 申请人要求气象主管机构对公示内容予以说明、解释的，气象主管机构应当说明、解释，提供准确、可靠的信息。"},{"i":18,"n":"第十八条","txt":"申请人申请气象行政许可，应当如实向气象主管机构提交有关材料和反映真实情况，并对其申请材料实质内容的真实性负责。气象主管机构不得要求申请人提交与其申请的气象行政许可事项无关的技术资料和其他材料。 办理气象行政许可的工作人员在收到申请人提交的申请材料后，除依法可以当场作出不予受理决定外，应当及时将收到行政许可申请时间、申请人、申请事项、提交材料情况等进行登记。"},{"i":19,"n":"第十九条","txt":"气象主管机构对申请人提出的气象行政许可申请，应当根据下列情况分别作出处理： （一）申请事项依法不需要取得气象行政许可的，应当即时告知申请人不受理； （二）申请事项依法不属于本气象主管机构职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在5日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （五）申请事项属于本气象主管机构职权范围，申请材料齐全、符合法定形式或者申请人按照本气象主管机构的要求提交全部补正申请材料的，应当受理行政许可申请。 气象主管机构受理或者不予受理行政许可申请，应当出具加盖本气象主管机构专用印章和注明日期的书面凭证。不予受理的，还应当说明理由。"},{"i":20,"n":"第二十条","txt":"申请人提交的申请材料齐全、符合法定形式、气象主管机构能够当场作出决定的，应当当场作出书面的行政许可决定。需要对申请材料的实质内容进行核实的，应当指派2名以上工作人员进行核查，制作现场核查记录，并由核查人员和被核查方签字确认。"},{"i":21,"n":"第二十一条","txt":"依法应当先经下级气象主管机构审查后报上级气象主管机构决定的气象行政许可，下级气象主管机构受理申请后，应当在法定期限内进行初步审查，审查完毕后将初审建议和全部申请材料直接报送上级气象主管机构。上级气象主管机构不得要求申请人重复提供申请材料。"},{"i":22,"n":"第二十二条","txt":"气象主管机构在审查气象行政许可申请时，涉及专业知识或者技术问题需要评审、评价或者检测的，可以委托专业机构或者专家进行评审、评价或者检测，并由专业机构或者专家出具评审、评价建议或者检测报告。 气象主管机构应当参考评审、评价建议或者检测报告作出行政许可决定。"},{"i":23,"n":"第二十三条","txt":"法律、法规、规章规定实施气象行政许可应当听证的事项，或者气象主管机构认为需要听证的其他涉及公共利益的重大气象行政许可事项，气象主管机构应当向社会公告，并按照《中华人民共和国行政许可法》的有关规定举行听证。"},{"i":24,"n":"第二十四条","txt":"申请人的申请符合法定条件的，气象主管机构应当依法作出准予行政许可的书面决定。气象主管机构依法作出不予行政许可的书面决定的，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":25,"n":"第二十五条","txt":"气象主管机构作出准予行政许可的决定，依法需要颁发行政许可证件的，应当向申请人颁发加盖本气象主管机构印章的行政许可证件。 气象行政许可证件可以采取以下形式： （一）许可证或者其他许可证书； （二）资质证或者其他合格证书； （三）批准文件或者证明文件； （四）法律、法规规定的其他行政许可证件。"},{"i":26,"n":"第二十六条","txt":"除当场作出行政许可决定的外，气象主管机构应当自受理气象行政许可申请之日起20日内作出行政许可决定。20日内不能作出决定的，经本气象主管机构负责人批准，可以延长10日，并应当将延长期限的理由告知申请人。 先经下级气象主管机构审查后报上级气象主管机构决定的气象行政许可，下级气象主管机构应当自其受理气象行政许可申请之日起20日内审查完毕。 依法需要听证、评审、评价、检测、鉴定的，应当在受理气象行政许可申请之日起3个月内进行，所需时间不计算在本办法规定的期限内，但应当将所需时间书面告知申请人。 法律、法规另有规定的，依照其规定。"},{"i":27,"n":"第二十七条","txt":"被许可人要求变更气象行政许可事项，符合法定条件、标准的，作出行政许可决定的气象主管机构应当在受理申请之日起20日内依法办理变更手续，并作出准予变更行政许可的决定；不符合法定条件、标准的，应当作出不予变更行政许可的决定。"},{"i":28,"n":"第二十八条","txt":"被许可人需要延续依法取得的气象行政许可的有效期的，应当在该行政许可有效期届满30日前向作出行政许可决定的气象主管机构提出申请。法律、法规、规章另有规定的，依照其规定。 气象主管机构应当根据被许可人的申请，在该行政许可有效期届满前作出是否准予延续的决定；逾期未作决定的，视为准予延续。"},{"i":29,"n":"第二十九条","txt":"气象主管机构应当对公民、法人或者其他组织从事气象行政许可事项的活动实施监督检查。 气象主管机构依法对被许可人从事行政许可事项的活动进行检查时，应当将检查的情况和处理结果予以记录，由执法检查人员签字后归档。除涉及国家秘密、商业秘密或者个人隐私事项外，公众有权查阅执法检查记录。"},{"i":30,"n":"第三十条","txt":"上级气象主管机构应当加强对下级气象主管机构实施行政许可的监督检查，及时纠正实施气象行政许可过程中的违法行为。 气象主管机构的内设机构承担具体业务范围内行政许可的监督检查工作，并以本级气象主管机构的名义开展监督检查。"},{"i":31,"n":"第三十一条","txt":"公民、法人或者其他组织发现违法从事气象行政许可事项活动的，有权向气象主管机构举报，气象主管机构应当及时核实、处理。"},{"i":32,"n":"第三十二条","txt":"被许可人在作出行政许可决定的气象主管机构管辖区域外违法从事气象行政许可事项活动的，违法行为发生地的气象主管机构应当依法作出处理，并将被许可人的违法事实、处理结果抄告作出行政许可决定的气象主管机构。"},{"i":33,"n":"第三十三条","txt":"气象主管机构在执法检查时，发现直接关系公共安全、人身健康、生命财产安全的重要设备、设施存在安全隐患的，应当责令停止使用，并限期改正。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，作出行政许可决定的气象主管机构或者其上级气象主管机构，根据利害关系人的请求或者依据职权，可以撤销气象行政许可： （一）气象主管机构工作人员滥用职权、玩忽职守作出准予行政许可决定的； （二）超越法定职权作出准予行政许可决定的； （三）违反法定程序作出准予行政许可决定的； （四）对不具备申请资格或者不符合法定条件的申请人准予行政许可的； （五）依法可以撤销气象行政许可的其他情形。 依照本条第一款的规定撤销气象行政许可，被许可人的合法权益受到损害的，气象主管机构应当依法给予赔偿。 被许可人以欺骗、贿赂等不正当手段取得气象行政许可的，应当予以撤销。被许可人基于气象行政许可取得的利益不受保护。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一的，气象主管机构应当依法办理有关气象行政许可的注销手续。注销行政许可，应当作出书面决定，并告知申请人注销的理由和依据： （一）气象行政许可有效期届满未延续的； （二）法人或者其他组织依法终止的； （三）气象行政许可依法被撤销、撤回，或者气象行政许可证件依法被吊销的； （四）因不可抗力导致气象行政许可事项无法实施的； （五）法律、法规规定的应当注销气象行政许可的其他情形。"},{"i":36,"n":"第三十六条","txt":"气象主管机构及其工作人员违反本办法的规定，有下列情形之一的，由其上级气象主管机构责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分： （一）对符合法定条件的气象行政许可不予受理的； （二）不在办公场所公示应当公示的材料的； （三）在受理、审查、决定气象行政许可过程中，未向申请人履行法定告知义务的； （四）申请人提交的申请材料不齐全、不符合法定形式，不一次告知申请人必须补正全部内容的； （五）未依法说明不受理气象行政许可申请或者不予气象行政许可理由的； （六）依法应当举行听证而不举行听证的。"},{"i":37,"n":"第三十七条","txt":"气象主管机构工作人员办理气象行政许可、实施监督检查，索取或者收受他人财物或者谋取其他利益，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":38,"n":"第三十八条","txt":"气象主管机构实施行政许可，有下列情形之一的，由其上级气象主管机构责令改正，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人准予行政许可或者超越法定职权作出准予行政许可决定的； （二）对符合法定条件的申请人不予行政许可或者不在法定期限内作出准予行政许可决定的。"},{"i":39,"n":"第三十九条","txt":"申请人隐瞒有关情况或者提供虚假材料申请气象行政许可的，气象主管机构不予受理或者不予行政许可，并给予警告；气象行政许可申请属于施放气球、雷电防护等直接关系公共安全、人身健康、生命财产安全事项的，申请人在1年内不得再次申请该气象行政许可。"},{"i":40,"n":"第四十条","txt":"被许可人以欺骗、贿赂等不正当手段取得气象行政许可的，气象主管机构应当撤销该行政许可，可并处3万元以下的罚款；取得的气象行政许可属于施放气球、雷电防护等直接关系公共安全、人身健康、生命财产安全事项的，申请人在3年内不得再次申请该气象行政许可；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"被许可人有下列行为之一的，由有关气象主管机构按照权限给予警告，责令改正，撤销该气象行政许可，可以并处3万元以下的罚款；构成犯罪的，依法追究刑事责任： （一）涂改、伪造、倒卖、出租、出借气象行政许可证件，或者以其他形式非法转让气象行政许可的； （二）超越气象行政许可范围进行活动的； （三）向负责监督检查的气象主管机构隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况的真实材料的。"},{"i":42,"n":"第四十二条","txt":"公民、法人或者其他组织未经行政许可，擅自从事依法应当取得气象行政许可的活动的，由有关气象主管机构依照有关法律法规规章进行处罚。"},{"i":43,"n":"第四十三条","txt":"气象主管机构实施行政许可和对行政许可进行监督检查，不得收取任何费用。但是，法律、行政法规另有规定的，依照其规定。 实施气象行政许可所需经费应当列入气象主管机构的财政预算，由财政予以保障。"},{"i":44,"n":"第四十四条","txt":"本办法规定的气象主管机构实施气象行政许可的期限以工作日计算，不含法定节假日。"},{"i":45,"n":"第四十五条","txt":"本办法未作规定的事项，按照《中华人民共和国行政许可法》的有关规定执行。 有关部门规章对气象行政许可有特殊规定的，依照其规定。 台湾、香港、澳门地区的组织和个人在中华人民共和国领域及其管辖的其他海域单独或者合作从事气象活动，参照本办法执行。"},{"i":46,"n":"第四十六条","txt":"本办法自2017年5月1日起施行。2006年11月24日公布的中国气象局第15号令《气象行政许可实施办法》和2008年10月9日公布的中国气象局第17号令《中国气象局关于修改〈气象行政许可实施办法〉的决定》同时废止。"}],"qixiangziliaogongxiangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强气象资料共享，进一步促进气象资料更好地为经济建设、国防建设、社会发展和人民生活服务，依据《中华人民共和国气象法》有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"各级气象主管机构组织提供气象资料共享，以及用户使用其提供共享的气象资料，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称气象资料，是指各级气象主管机构组织收集并存档的各种气象观(探)测记录，以及由这些记录加工处理而成的各类气象数据集、各种气候统计值和数值分析资料等。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构负责全国气象资料共享工作的管理。地方各级气象主管机构负责本行政区域内气象资料共享工作的管理。"},{"i":5,"n":"第五条","txt":"提供涉密气象资料共享，以及使用、保管共享的涉密气象资料，应当遵守《中华人民共和国保守国家秘密法》和《气象部门保守国家秘密实施细则》等有关规定。"},{"i":6,"n":"第六条","txt":"各级气象主管机构负责共享气象资料提供工作的单位，应当通过网络适时、滚动向社会发布下列基本气象资料，供公众无偿下载： (一)我国参加世界气象组织全球通信系统(GTS)交换的地面气象站的定时(4次)观测报告和高空站的定时(2次)观测报告； (二)我国参加地面气候资料国际交换的气象站(附件)的气温、气压、湿度、风、降水、日照等要素的当年的月、年统计值。"},{"i":7,"n":"第七条","txt":"各级气象主管机构负责共享气象资料提供工作的单位，应当免费向从事气象工作的机构、事业单位开展的公益服务、非营利性科研和教育机构从事的非商业性活动提供所需的气象资料。 有关部门和单位与气象部门合作开展的业务和科研项目所需的气象资料，按双方建立合作关系时商定的原则和方法处理。 为企业、事业单位从事的经营性活动提供所需的气象资料，除收取资料复制和交付成本费外，可以补偿性收取资料加工处理费。"},{"i":8,"n":"第八条","txt":"各级气象主管机构负责共享气象资料提供工作的单位，为各级党委、人民政府及其防灾减灾机构，以及外国驻华使馆、领事馆、联合国驻华机构提供其开展公务活动所需的气象资料，不收取费用。"},{"i":9,"n":"第九条","txt":"国务院气象主管机构负责共享气象资料提供工作的单位，向用户提供从其他国家气象部门交换来的气象资料，必须遵守有关国家气象部门提供交换资料时附加的使用限制条件。 各级气象主管机构负责共享气象资料提供工作的单位，向用户提供从其他从事气象工作的机构、有关部门和科研单位交换来的资料，应当遵守有关机构、部门和单位提供交换资料时附加的使用限制条件。"},{"i":10,"n":"第十条","txt":"各级气象主管机构负责共享气象资料提供工作的单位，只负责提供本级气象主管机构组织收集和存档的气象资料。 除各级气象主管机构负责共享气象资料提供工作的单位之外，各级气象主管机构所属的其他单位和个人不得从事或变相从事气象资料提供工作。"},{"i":11,"n":"第十一条","txt":"用户要求提供气象资料时，应当凭有效证件，并提交包括所索取气象资料的用途、类别、范围、数量，以及是否涉外使用等内容的证明文件。"},{"i":12,"n":"第十二条","txt":"用户对各级气象主管机构组织提供的气象资料，只享有有限的、不排他的使用权。"},{"i":13,"n":"第十三条","txt":"用户不得有偿或无偿转让其从各级气象主管机构获得的气象资料，包括用户对这些气象资料进行单位换算、介质转换或者量度变换后形成的新资料，以及对其进行实质性加工后形成的新资料。"},{"i":14,"n":"第十四条","txt":"用户不得直接将其从各级气象主管机构获得的气象资料，用作向外分发或供外部使用的数据库、产品和服务的一部分，也不得间接用作生成它们的基础。 用户从各级气象主管机构获得气象资料，可以在内部分发；可以存放在仅供本单位使用的局域网上，但不得与广域网、互联网相连接。"},{"i":15,"n":"第十五条","txt":"用户从各级气象主管机构获得的用于非经营性活动的气象资料，不得用于经营性活动。"},{"i":16,"n":"第十六条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构责令其改正，给予警告，并处以一万元以下罚款；情节严重的，停止向其提供气象资料： (一)将所获得的气象资料或者这些气象资料的使用权，向国内外其他单位和个人无偿转让的； (二)将所获得气象资料直接向外分发或用作供外部使用的数据库、产品和服务的一部分，或者间接用作生成它们的基础的； (三)将存放所获得气象资料的局域网与广域网、互联网相连接的； (四)将所获得气象资料进行单位换算、介质转换或者量度变换后形成的新资料，或者对所获得气象资料进行实质性加工后形成的新资料向外分发的； (五)不按要求使用从国内外交换来的气象资料的。"},{"i":17,"n":"第十七条","txt":"违反本办法规定，将所获得的气象资料或者这些气象资料的使用权，向国内外其他单位和个人有偿转让的，由有关气象主管机构责令其改正，给予警告，并处以三万元以下的罚款；情节严重的，停止向其提供气象资料。"},{"i":18,"n":"第十八条","txt":"违反本办法规定，将通过网络无偿下载的或按公益使用免费获取的气象资料，用于经营性活动的，由有关气象主管机构责令其改正，给予警告，并处以五万元以下罚款。情节严重的，停止向其提供气象资料。"},{"i":19,"n":"第十九条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构责令其限期改正；情节严重的，对责任人员依法给予行政处分： (一)不适时向社会发布基本气象资料的； (二)不免费向从事气象工作的机构、国内非营利性科研和教育机构从事的非商业性活动提供气象资料的； (三)不及时向各级党委、人民政府，以及外国驻华使馆、领事馆、联合国驻华机构提供其开展公务活动所需气象资料的； (四)向用户提供与其他国家气象部门交换来的气象资料，不遵守有关国家气象部门提供交换资料时附加的使用限制条件的； (五)向用户提供与其他从事气象工作的机构、有关部门和科研单位交换来的气象等资料，不遵守有关机构、部门和单位提供交换资料时附加的使用限制条件的。"},{"i":20,"n":"第二十条","txt":"提供涉密气象资料共享，以及使用、保管共享的涉密气象资料，不遵守《中华人民共和国保守国家秘密法》和《气象部门保守国家秘密实施细则》等法律、法规等规定的，由有关部门依照上述法律、法规的规定进行处罚。"},{"i":21,"n":"第二十一条","txt":"本办法中下列术语的含义是： (一)用户，是指独立法人单位，不含其下属单位。 (二)免费，按世界气象组织40号(Cg-XII)决议给出的定义，是指除复制和交付资料所需的成本费外，不再征收任何资料采集和存档所花的费用。 (三)资料复制和交付成本费，是指为用户提供气象资料过程中对气象资料检索、摘录、加工、复制所需的人员工时、设备损耗、能源消耗以及复制载体、通讯传输等项费用。 (四)资料加工处理费，是指对所收集的气象资料进行加工处理和归档所需的人员工时、设备损耗、能源消耗等项费用。"},{"i":22,"n":"第二十二条","txt":"为索取气象资料的外国机构和个人提供气象资料，可参照本办法有关条款的规定执行。"},{"i":23,"n":"第二十三条","txt":"各级气象主管机构可以根据本办法制定具体的实施办法。"},{"i":24,"n":"第二十四条","txt":"本办法由国务院气象主管机构负责解释。"},{"i":25,"n":"第二十五条","txt":"本办法自公布之日起施行。"}],"qixiangyubaofabuyuchuanboguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范气象预报发布，鼓励气象预报传播，更好地为经济社会发展和人民生活服务，根据《中华人民共和国气象法》和《气象灾害防御条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域内从事气象预报发布与传播活动的，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称气象预报包括公众气象预报、灾害性天气警报和气象灾害预警信号。 本办法所称公众气象预报是指面向社会公众发布的天气现象、云、风向、风速、气温、湿度、气压、降水、能见度等气象要素预报，以及日地空间天气现象、太阳活动水平、地磁活动水平、电离层活动水平、空间粒子辐射环境、中高层大气状态参数等空间天气要素预报。 本办法所称灾害性天气警报和气象灾害预警信号是指台风、暴雨、暴雪、寒潮、大风、沙尘暴、低温、高温、干旱、雷电、冰雹、霜冻、大雾、霾、道路结冰等气象灾害预警信息，以及太阳耀斑、太阳质子事件、日冕物质抛射、磁暴、电离层暴等空间天气灾害预警信息。 本办法所称气象预报发布是指气象预报向社会无偿公开的过程。 本办法所称气象预报传播是指将已发布的气象预报进行转播、转载的过程。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构和国务院有关部门应当按照职责分工，共同做好全国气象预报发布与传播工作，并加强监督管理。 地方各级气象主管机构和县级以上地方人民政府有关部门应当按照职责分工，共同做好本行政区域内的气象预报发布与传播工作，并加强监督管理。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府应当组织新闻出版广播电视、电信、交通运输、气象、互联网等有关部门和单位建立完善气象预报发布和传播渠道。 传播气象预报的媒体和单位应当与当地气象主管机构所属的气象台建立获取最新气象预报机制，确保气象预报及时准确传播。"},{"i":6,"n":"第六条","txt":"气象预报实行统一发布制度。各级气象主管机构所属的气象台应当按照职责通过气象预报发布渠道向社会发布，并根据天气变化情况及时更新发布气象预报。 其他任何组织或个人不得以任何形式向社会发布气象预报。"},{"i":7,"n":"第七条","txt":"各级人民政府指定的媒体和单位应当安排固定的时间和频率、频道、版面、页面，及时传播气象主管机构所属的气象台提供的最新气象预报。广播、电视台（站）改变气象预报节目播发时间安排的，应当事先征得当地气象主管机构所属的气象台的同意。"},{"i":8,"n":"第八条","txt":"各级人民政府应当组织气象等有关部门建立气象灾害预警信息快速发布和传播机制。可能或已经发生重大灾害性天气时，媒体和单位应当根据气象主管机构所属的气象台的要求及时增播、插播重要灾害性天气警报和气象灾害预警信号。 灾害性天气警报和气象灾害预警信号解除时，媒体和单位应当及时更新，不得传播过时的灾害性天气警报和气象灾害预警信号。"},{"i":9,"n":"第九条","txt":"鼓励媒体和单位传播气象预报。媒体和单位传播气象预报应当使用当地气象主管机构所属的气象台提供的最新气象预报，并注明气象预报发布的气象台名称和发布时间，不得自行更改气象预报的内容和结论。"},{"i":10,"n":"第十条","txt":"科研教学单位、学术团体和个人研究形成的气象预报意见和结论可以提供给气象主管机构所属的气象台制作气象预报时参考，但不得以任何形式向社会公开发布。"},{"i":11,"n":"第十一条","txt":"国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门所属的气象台站，可以发布供本系统使用的专项气象预报，但不得以任何形式向社会公开发布。"},{"i":12,"n":"第十二条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构按照权限责令改正，给予警告，可以并处5万元以下罚款： （一）非法发布气象预报的； （二）向社会传播气象预报不使用当地气象主管机构所属的气象台提供的最新气象预报的。"},{"i":13,"n":"第十三条","txt":"各级气象主管机构所属的气象台工作人员，由于玩忽职守，导致未按规定发布气象预报造成严重后果的，依法给予行政处分；致使国家利益和人民生命财产遭到重大损失，构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构按照权限责令改正，给予警告，可以并处3万元以下罚款；造成人员伤亡或重大财产损失，构成犯罪的，依法追究刑事责任。 （一）传播虚假气象预报的； （二）不按规定及时增播、插播重要灾害性天气警报、气象灾害预警信号和更新气象预报的； （三）向社会传播气象预报不注明发布单位名称和发布时间的； （四）擅自更改气象预报内容和结论，引起社会不良反应或造成一定影响的。"},{"i":15,"n":"第十五条","txt":"本办法自2015年5月1日起实施，2003年12月31日中国气象局公布的《气象预报发布与刊播管理办法》（中国气象局令第6号）同时废止。"}],"shewaiqixiangtanceheziliaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范涉外气象探测和资料管理，维护国家安全和利益，根据《中华人民共和国国家安全法》《中华人民共和国保守国家秘密法》和《中华人民共和国气象法》及其他有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"外国组织和个人在中华人民共和国领域和中华人民共和国管辖的其他海域从事气象探测以及汇交、获取、提供和使用气象资料等活动，应当遵守本办法。 外国组织和个人在中华人民共和国领域和中华人民共和国管辖的其他海域从事前款所述活动，应当与中华人民共和国有关组织合作进行。"},{"i":3,"n":"第三条","txt":"从事涉外气象探测以及汇交、获取、提供和使用气象资料等活动, 应当坚持依法监管、有效利用的原则，维护国家安全，促进气象国际合作。 涉及国家安全、国家秘密的涉外气象探测和气象资料的汇交、获取、提供和使用等活动，应当遵守国家安全和保密的法律、法规、规章和有关规定。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构负责全国涉外气象探测和资料的管理。 地方各级气象主管机构负责本行政区域内的涉外气象探测和资料的管理。 国家安全、保密等国务院其他有关部门和地方各级人民政府其他有关部门,应当按照职责配合气象主管机构共同做好涉外气象探测和资料的管理工作。"},{"i":5,"n":"第五条","txt":"任何组织和个人不得向未经批准的外国组织或者个人提供气象探测场所和气象资料。 外国组织和个人不得利用气象探测活动和气象资料损害中华人民共和国的国家安全和利益。 国家机关和涉及国家秘密的单位不得擅自将涉及国家秘密的气象资料提供给外国组织或者个人。其他组织和个人不得将涉及国家秘密的气象资料以任何方式提供给外国组织或者个人。 涉及国家秘密的气象资料不得以任何方式发表。"},{"i":6,"n":"第六条","txt":"涉外气象探测站（点）的设立，实行行政许可制度。未经许可，不得设立涉外气象探测站（点）。 国务院气象主管机构负责涉外气象探测站（点）设立的审批，涉及国家安全、国家秘密的，应当分别征求国家安全、保密等部门的意见。 省、自治区、直辖市气象主管机构应当按照国务院气象主管机构有关要求，做好涉外气象探测站（点）设立的技术审查（含现场踏勘）工作。涉及国家安全、国家秘密的，应当分别征求同级国家安全、保密等部门的意见。"},{"i":7,"n":"第七条","txt":"申请设立涉外气象探测站（点）应当具备以下条件： （一）具有科学合理的国际合作项目实施计划或者方案； （二）具有明确的中方合作组织、符合要求的气象探测地点； （三）具有相应的经费、设备和专业技术人员; （四）涉外气象探测活动的项目需要其他有关部门批准的，应当先经其他有关部门批准。"},{"i":8,"n":"第八条","txt":"申请设立涉外气象探测站（点）,应当提交以下材料： （一）合作各方的基本情况； （二）合作项目协议书、项目实施计划或者方案； （三）专业技术人员的基本情况； （四）气象探测仪器设备的型号、生产厂家、设备许可证或者技术指标等； （五）拟建气象探测站（点）的基本参数（包括经度、纬度、海拔等）、布点数和气象探测环境； （六）气象探测项目、时段，采样时间、频次、计算方法及其用途； （七）气象探测资料的处理和传输方式，数据的采集、传输和存档格式，国内备份以及数据使用的共享方式等。"},{"i":9,"n":"第九条","txt":"申请设立涉外气象探测站（点），应当按照以下程序办理： （一）开展涉外气象探测活动的中方合作组织，应当向国务院气象主管机构提出申请； （二）国务院气象主管机构自收到全部申请材料之日起五个工作日内，按照《中华人民共和国行政许可法》第三十二条的规定作出受理或者不予受理的决定，并出具书面凭证，对于不予受理的，应当说明理由； （三）国务院气象主管机构受理后，可以委托申请人所在地和拟设立涉外气象探测站（点）所在地的省、自治区、直辖市气象主管机构进行技术审查（含现场踏勘），若同一申请中涉及多个涉外气象探测站（点）且跨行政区域的，可以委托两个以上省、自治区、直辖市气象主管机构分别进行技术审查； （四）国务院气象主管机构应当结合申请人申请材料和技术审查意见作出决定，并通报涉外气象探测站（点）所在地的省、自治区、直辖市气象主管机构。 中方合作组织必须如实向气象主管机构提交有关材料和反映真实情况，并对其申请"},{"i":10,"n":"第十条","txt":"国务院气象主管机构应当自受理之日起二十个工作日内作出许可决定。二十个工作日内不能作出决定的，按照《中华人民共和国行政许可法》第四十二条第一款的规定执行。 国务院气象主管机构依法作出不予行政许可的书面决定的，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。 国务院气象主管机构在审批过程中需要按照《中华人民共和国行政许可法》第四十五条规定进行技术审查（含现场踏勘）的，所需时间不计入审批期限内。技术审查（含现场踏勘）时间一般不超过三个月。国务院气象主管机构应当将所需时间书面告知申请人。"},{"i":11,"n":"第十一条","txt":"申请设立涉外气象探测站（点）和利用已有气象站（点）或者自带仪器设备进行气象探测的，应当遵守以下要求： （一）在我国境内设立气象探测站点的站间距不能小于六十公里，探测时间不能超过两年，有特别需要并经国务院气象主管机构批准的除外； （二）所获取的气象资料未经气象主管机构同意不得单方面进行传输； （三）自带和使用的气象探测仪器设备，应当符合国家安全和保密的法律、法规、规章和有关规定，并接受国务院气象主管机构或者省、自治区、直辖市气象主管机构会同国家安全和保密部门的监督检查； （四）自带和使用的气象探测仪器设备属于无线电发射设备的，应当按照国家无线电管理有关规定办理相关手续； （五）涉外气象探测不得对我国正在进行的气象探测工作造成影响； （六）不得进入涉及国家安全的区域开展气象探测活动； （七）不得通过探测获取涉及国家秘密的气象资料。"},{"i":12,"n":"第十二条","txt":"国防及军事设施区域、军事敏感区域、尚未对外开放地区、重点工程建设区域及其他涉及国家安全的区域不得设立涉外气象探测站（点）。"},{"i":13,"n":"第十三条","txt":"经国务院气象主管机构批准设立的涉外气象探测站（点），应当按照批准的气象探测地点、项目、时段进行探测，不得擅自变更。 需要变更气象探测地点、项目、时段的，应当重新申请，并经国务院气象主管机构批准。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市气象主管机构负责本行政区域内涉外气象探测站（点）的监督管理，并将监督管理情况及时报告国务院气象主管机构。 中外合作各方应当主动接受气象主管机构的监督检查，如实提供有关情况和材料。"},{"i":15,"n":"第十五条","txt":"涉外气象探测活动所获取的气象探测资料,应当及时向气象探测站（点）所在地的省、自治区、直辖市气象主管机构汇交。具体汇交按照国务院气象主管机构制定的《气象探测资料汇交管理办法》执行。"},{"i":16,"n":"第十六条","txt":"涉外气象探测活动所获取的气象探测资料及其加工产品，归中华人民共和国所有。"},{"i":17,"n":"第十七条","txt":"外国组织和个人对其通过涉外气象探测活动所获取的气象探测资料及其加工产品享有使用权，参加合作各方可以依照约定使用，但不得以任何形式转让、提供给第三方。"},{"i":18,"n":"第十八条","txt":"外国组织和个人申请获取参加世界气象组织全球和区域交换站点以外的气象资料，应当由中方合作组织向省、自治区、直辖市气象主管机构提出书面申请，由省、自治区、直辖市气象主管机构或者国务院气象主管机构批准。 中外合作各方应当与气象资料提供方签订气象资料使用协议，对获得的气象资料及其加工产品应当依照协议约定使用。协议应当报送省、自治区、直辖市气象主管机构或者国务院气象主管机构备案。"},{"i":19,"n":"第十九条","txt":"在对外交往和合作中需要向外国组织或者个人提供涉及国家秘密的气象资料，应当按照国家保密法律、法规和有关规定执行。"},{"i":20,"n":"第二十条","txt":"外国组织和个人在涉外气象探测活动中需要获取涉及国家秘密的气象资料，应当按照国家保密法律、法规和有关规定报批，并由国务院气象主管机构或者其授权的单位与中外合作各方按照国家规定签订气象资料保密协议，明确保密义务和责任，并依照协议约定使用。"},{"i":21,"n":"第二十一条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构责令停止违法行为，限期改正，给予警告，可以并处三万元以下的罚款；构成犯罪的，依法追究刑事责任： （一）未经批准擅自设立涉外气象探测站（点）的； （二）超出批准布点数探测的； （三）对我国正在进行的气象探测工作造成影响的； （四）未经批准变更气象探测地点、项目、时段的； （五）超过气象探测期限进行探测活动的； （六）自带或者使用的气象探测仪器设备未经国务院气象主管机构或者省、自治区、直辖市气象主管机构会同国家安全和保密部门的监督检查的； （七）所获取的气象资料未经气象主管机构同意单方面进行传输的。"},{"i":22,"n":"第二十二条","txt":"违反本办法规定，有下列行为之一的，由有关气象主管机构责令停止违法行为，限期改正，给予警告，可以并处三万元以下的罚款： （一）向未经批准的外国组织或者个人提供气象探测场所和气象资料的； （二）外国组织和个人实施或者指使、资助他人以非法手段收集、窃取气象资料的； （三）未按照规定向有关气象主管机构汇交气象探测资料的； （四）转让或者提供气象探测资料及其加工产品给第三方的。"},{"i":23,"n":"第二十三条","txt":"在涉外气象探测和资料管理活动中违反国家安全和保密法律、法规、规章和有关规定的，由国家安全、保密等部门依法处理；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"气象主管机构工作人员在涉外气象探测和资料管理工作中玩忽职守、滥用职权的，依法给予处分；构成犯罪的，依法追究刑事责任。 国家工作人员在涉外气象探测和资料管理工作中故意或者过失泄露涉及国家秘密的气象资料的，按照国家有关法律法规规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"本办法中下列用语的含义是： （一）气象探测，是指利用科技手段对大气和近地层的大气物理过程、现象及其化学性质等进行的系统观察和测量； （二）气象探测站（点），是指涉外气象活动中收集或者测量气象要素的临时或固定的设备及其场所。"},{"i":26,"n":"第二十六条","txt":"我国政府与外国政府及国际组织之间的合作项目中涉及的气象活动，按照国家有关规定执行。 香港特别行政区、澳门特别行政区、台湾地区的组织和个人从事气象探测以及汇交、获取、提供和使用气象资料等活动，参照本办法执行。"},{"i":27,"n":"第二十七条","txt":"本办法自2022年8月1日起施行。2006年11月7日公布的中国气象局 国家保密局第13号令《涉外气象探测和资料管理办法》同时废止。"}],"fangleijianzaiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强雷电灾害防御工作，规范雷电灾害管理，提高雷电灾害防御能力和水平，保护国家利益和人民生命财产安全，维护公共安全，促进经济建设和社会发展，依据《中华人民共和国气象法》、《中华人民共和国行政许可法》和《气象灾害防御条例》等法律、法规的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域内从事雷电灾害防御活动的组织和个人，应当遵守本办法。 本办法所称雷电灾害防御（以下简称防雷减灾），是指防御和减轻雷电灾害的活动，包括雷电和雷电灾害的研究、监测、预警、风险评估、防护以及雷电灾害的调查、鉴定等。"},{"i":3,"n":"第三条","txt":"防雷减灾工作，实行安全第一、预防为主、防治结合的原则。"},{"i":4,"n":"第四条","txt":"国务院气象主管机构负责组织管理和指导全国防雷减灾工作。 地方各级气象主管机构在上级气象主管机构和本级人民政府的领导下，负责组织管理本行政区域内的防雷减灾工作。 国务院其他有关部门和地方各级人民政府其他有关部门应当按照职责做好本部门和本单位的防雷减灾工作，并接受同级气象主管机构的监督管理。"},{"i":5,"n":"第五条","txt":"国家鼓励和支持防雷减灾的科学技术研究和开发，推广应用防雷科技研究成果，加强防雷标准化工作，提高防雷技术水平，开展防雷减灾科普宣传，增强全民防雷减灾意识。"},{"i":6,"n":"第六条","txt":"外国组织和个人在中华人民共和国领域和中华人民共和国管辖的其他海域从事防雷减灾活动，应当经国务院气象主管机构会同有关部门批准，并在当地省级气象主管机构备案，接受当地省级气象主管机构的监督管理。"},{"i":7,"n":"第七条","txt":"国务院气象主管机构应当组织有关部门按照合理布局、信息共享、有效利用的原则，规划全国雷电监测网，避免重复建设。 地方各级气象主管机构应当组织本行政区域内的雷电监测网建设，以防御雷电灾害。"},{"i":8,"n":"第八条","txt":"各级气象主管机构应当加强雷电灾害预警系统的建设工作，提高雷电灾害预警和防雷减灾服务能力。"},{"i":9,"n":"第九条","txt":"各级气象主管机构所属气象台站应当根据雷电灾害防御的需要，按照职责开展雷电监测，并及时向气象主管机构和有关灾害防御、救助部门提供雷电监测信息。 有条件的气象主管机构所属气象台站可以开展雷电预报，并及时向社会发布。"},{"i":10,"n":"第十条","txt":"各级气象主管机构应当组织有关部门加强对雷电和雷电灾害的发生机理等基础理论和防御技术等应用理论的研究，并加强对防雷减灾技术和雷电监测、预警系统的研究和开发。"},{"i":11,"n":"第十一条","txt":"各类建（构）筑物、场所和设施安装的雷电防护装置（以下简称防雷装置），应当符合国家有关防雷标准和国务院气象主管机构规定的使用要求，并由具有相应资质的单位承担设计、施工和检测。 本办法所称防雷装置，是指接闪器、引下线、接地装置、电涌保护器及其连接导体等构成的，用以防御雷电灾害的设施或者系统。"},{"i":12,"n":"第十二条","txt":"对从事防雷工程专业设计和施工的单位实行资质认定。 本办法所称防雷工程，是指通过勘察设计和安装防雷装置形成的雷电灾害防御工程实体。 防雷工程专业设计或者施工资质分为甲、乙、丙三级，由省、自治区、直辖市气象主管机构认定。"},{"i":13,"n":"第十三条","txt":"防雷工程专业设计或者施工单位，应当按照有关规定取得相应的资质证书后，方可在其资质等级许可的范围内从事防雷工程专业设计或者施工。具体办法由国务院气象主管机构另行制定。"},{"i":14,"n":"第十四条","txt":"防雷工程专业设计或者施工单位，应当按照相应的资质等级从事防雷工程专业设计或者施工。禁止无资质或者超出资质许可范围承担防雷工程专业设计或者施工。"},{"i":15,"n":"第十五条","txt":"防雷装置的设计实行审核制度。 县级以上地方气象主管机构负责本行政区域内的防雷装置的设计审核。符合要求的，由负责审核的气象主管机构出具核准文件；不符合要求的，负责审核的气象主管机构提出整改要求，退回申请单位修改后重新申请设计审核。未经审核或者未取得核准文件的设计方案，不得交付施工。"},{"i":16,"n":"第十六条","txt":"防雷工程的施工单位应当按照审核同意的设计方案进行施工，并接受当地气象主管机构监督管理。 在施工中变更和修改设计方案的，应当按照原申请程序重新申请审核。"},{"i":17,"n":"第十七条","txt":"防雷装置实行竣工验收制度。 县级以上地方气象主管机构负责本行政区域内的防雷装置的竣工验收。 负责验收的气象主管机构接到申请后，应当根据具有相应资质的防雷装置检测机构出具的检测报告进行核实。符合要求的，由气象主管机构出具验收文件。不符合要求的，负责验收的气象主管机构提出整改要求，申请单位整改后重新申请竣工验收。未取得验收合格文件的防雷装置，不得投入使用。"},{"i":18,"n":"第十八条","txt":"出具检测报告的防雷装置检测机构，应当对隐蔽工程进行逐项检测，并对检测结果负责。检测报告作为竣工验收的技术依据。"},{"i":19,"n":"第十九条","txt":"投入使用后的防雷装置实行定期检测制度。防雷装置应当每年检测一次，对爆炸和火灾危险环境场所的防雷装置应当每半年检测一次。"},{"i":20,"n":"第二十条","txt":"防雷装置检测机构的资质由省、自治区、直辖市气象主管机构负责认定。"},{"i":21,"n":"第二十一条","txt":"防雷装置检测机构对防雷装置检测后，应当出具检测报告。不合格的，提出整改意见。被检测单位拒不整改或者整改不合格的，防雷装置检测机构应当报告当地气象主管机构，由当地气象主管机构依法作出处理。 防雷装置检测机构应当执行国家有关标准和规范，出具的防雷装置检测报告必须真实可靠。"},{"i":22,"n":"第二十二条","txt":"防雷装置所有人或受托人应当指定专人负责，做好防雷装置的日常维护工作。发现防雷装置存在隐患时，应当及时采取措施进行处理。"},{"i":23,"n":"第二十三条","txt":"已安装防雷装置的单位或者个人应当主动委托有相应资质的防雷装置检测机构进行定期检测，并接受当地气象主管机构和当地人民政府安全生产管理部门的管理和监督检查。"},{"i":24,"n":"第二十四条","txt":"各级气象主管机构负责组织雷电灾害调查、鉴定工作。 其他有关部门和单位应当配合当地气象主管机构做好雷电灾害调查、鉴定工作。"},{"i":25,"n":"第二十五条","txt":"遭受雷电灾害的组织和个人，应当及时向当地气象主管机构报告，并协助当地气象主管机构对雷电灾害进行调查与鉴定。"},{"i":26,"n":"第二十六条","txt":"地方各级气象主管机构应当及时向当地人民政府和上级气象主管机构上报本行政区域内的重大雷电灾情和年度雷电灾害情况。"},{"i":27,"n":"第二十七条","txt":"大型建设工程、重点工程、爆炸和火灾危险环境、人员密集场所等项目应当进行雷电灾害风险评估，以确保公共安全。 各级地方气象主管机构按照有关规定组织进行本行政区域内的雷电灾害风险评估工作。"},{"i":28,"n":"第二十八条","txt":"防雷产品应当符合国务院气象主管机构规定的使用要求。"},{"i":29,"n":"第二十九条","txt":"防雷产品应当由国务院气象主管机构授权的检测机构测试，测试合格并符合相关要求后方可投入使用。 申请国务院气象主管机构授权的防雷产品检测机构，应当按照国家有关规定通过计量认证、获得资格认可。"},{"i":30,"n":"第三十条","txt":"防雷产品的使用，应当到省、自治区、直辖市气象主管机构备案，并接受省、自治区、直辖市气象主管机构的监督检查。"},{"i":31,"n":"第三十一条","txt":"申请单位隐瞒有关情况、提供虚假材料申请资质认定、设计审核或者竣工验收的，有关气象主管机构不予受理或者不予行政许可，并给予警告。申请单位在一年内不得再次申请资质认定。"},{"i":32,"n":"第三十二条","txt":"被许可单位以欺骗、贿赂等不正当手段取得资质、通过设计审核或者竣工验收的，有关气象主管机构按照权限给予警告，可以处1万元以上3万元以下罚款；已取得资质、通过设计审核或者竣工验收的，撤销其许可证书；被许可单位3年内不得再次申请资质认定；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"违反本办法规定，有下列行为之一的，由县级以上气象主管机构按照权限责令改正，给予警告，可以处5万元以上10万元以下罚款；给他人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）涂改、伪造、倒卖、出租、出借、挂靠资质证书、资格证书或者许可文件的； （二）向负责监督检查的机构隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况的真实材料的。"},{"i":34,"n":"第三十四条","txt":"违反本办法规定，有下列行为之一的，由县级以上气象主管机构按照权限责令改正，给予警告，可以处5万元以上10万元以下罚款；给他人造成损失的，依法承担赔偿责任： （一）不具备防雷装置检测、防雷工程专业设计或者施工资质，擅自从事相关活动的； （二）超出防雷装置检测、防雷工程专业设计或者施工资质等级从事相关活动的； （三）防雷装置设计未经当地气象主管机构审核或者审核未通过，擅自施工的； （四）防雷装置未经当地气象主管机构验收或者未取得验收文件，擅自投入使用的。"},{"i":35,"n":"第三十五条","txt":"违反本办法规定，有下列行为之一的，由县级以上气象主管机构按照权限责令改正，给予警告，可以处1万元以上3万元以下罚款；给他人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）应当安装防雷装置而拒不安装的； （二）使用不符合使用要求的防雷装置或者产品的； （三）已有防雷装置，拒绝进行检测或者经检测不合格又拒不整改的； （四）对重大雷电灾害事故隐瞒不报的。"},{"i":36,"n":"第三十六条","txt":"违反本办法规定，导致雷击造成火灾、爆炸、人员伤亡以及国家财产重大损失的，由主管部门给予直接责任人行政处分；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"防雷工作人员由于玩忽职守，导致重大雷电灾害事故的，由所在单位依法给予行政处分；致使国家利益和人民生命财产遭到重大损失，构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"从事防雷专业技术的人员应当取得资格证书。 省级气象学会负责本行政区域内防雷专业技术人员的资格认定工作。防雷专业技术人员应当通过省级气象学会组织的考试，并取得相应的资格证书。 省级气象主管机构应当对本级气象学会开展防雷专业技术人员的资格认定工作进行监督管理。"},{"i":39,"n":"第三十九条","txt":"本办法自2011年9月1日起施行。2005年2月1日中国气象局公布的《防雷减灾管理办法》同时废止。"}],"leidianfanghuzhuangzhijiancezizhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强雷电防护装置检测资质管理，规范雷电防护装置检测行为，保护人民生命财产和公共安全，依据《中华人民共和国气象法》《气象灾害防御条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"申请雷电防护装置检测资质，实施对雷电防护装置检测资质的监督管理，适用本办法。 本办法所称雷电防护装置检测是指对接闪器、引下线、接地装置、电涌保护器及其连接导体等构成的，用以防御雷电灾害的设施或者系统进行检测的活动。"},{"i":3,"n":"第三条","txt":"国务院气象主管机构负责全国雷电防护装置检测资质的监督管理工作。 省、自治区、直辖市气象主管机构负责本行政区域内雷电防护装置检测资质的管理和认定工作。"},{"i":4,"n":"第四条","txt":"雷电防护装置检测资质等级分为甲、乙两级。 甲级资质单位可以从事《建筑物防雷设计规范》规定的第一类、第二类、第三类建（构）筑物的雷电防护装置的检测。 乙级资质单位可以从事《建筑物防雷设计规范》规定的第三类建（构）筑物的雷电防护装置的检测。"},{"i":5,"n":"第五条","txt":"《雷电防护装置检测资质证》分正本和副本，由国务院气象主管机构统一印制。资质证有效期为五年。"},{"i":6,"n":"第六条","txt":"雷电防护装置检测资质的认定应当遵循公开、公平、公正和便民、高效、信赖保护的原则。"},{"i":7,"n":"第七条","txt":"申请雷电防护装置检测资质的单位应当具备以下基本条件： （一）独立法人资格； （二）具有满足雷电防护装置检测业务需要的经营场所； （三）从事雷电防护装置检测工作的人员应当具备雷电防护装置检测能力；在具备雷电防护装置检测能力的人员中，应当有一定数量的与防雷、建筑、电子、电气、气象、通信、电力、计算机相关专业的高、中级专业技术人员，并在其从业单位参加社会保险； （四）具有雷电防护装置检测质量管理体系，并有健全的技术、档案和安全管理制度； （五）具有与所申请资质等级相适应的技术能力和良好信誉； （六）用于雷电防护装置检测的专用仪器设备应当经法定计量检定机构检定或者校准，并在有效期内。"},{"i":8,"n":"第八条","txt":"申请甲级资质的单位除了符合本办法第七条的基本条件外，还应当同时符合以下条件： （一）具备雷电防护装置检测能力的人员，其中具有高级技术职称的不少于二名，具有中级技术职称的不少于六名；技术负责人应当具有高级技术职称，从事雷电防护装置检测工作四年以上，并具备甲级资质等级要求的雷电防护装置检测专业知识和能力； （二）近三年内开展的雷电防护装置检测项目不少于二百个，且未因检测质量问题引发事故；雷电防护装置检测项目通过省、自治区、直辖市气象主管机构组织的质量考核合格率达百分之九十以上； （三）具有满足相应技术标准的专业设备（附表1）； （四）取得乙级资质三年以上。"},{"i":9,"n":"第九条","txt":"申请乙级资质的单位除了符合本办法第七条的基本条件外，还应当同时符合以下条件： （一）具备雷电防护装置检测能力的人员，其中具有高级技术职称的不少于一名，具有中级技术职称的不少于三名；技术负责人应当具有高级技术职称，从事雷电防护装置设计、施工、检测等工作两年以上，并具备乙级资质等级要求的雷电防护装置检测专业知识和能力； （二）具有满足相应技术标准的专业设备（附表1）。"},{"i":10,"n":"第十条","txt":"申请雷电防护装置检测资质的单位，应当向法人登记所在地的省、自治区、直辖市气象主管机构提出申请。"},{"i":11,"n":"第十一条","txt":"满足本办法第七条和第九条相应条件的，可以申请雷电防护装置检测的乙级资质。申请单位应当提交以下材料： （一）《雷电防护装置检测资质申请表》(附表2)； （二）《专业技术人员简表》(附表3)，具备雷电防护装置检测能力的专业技术人员技术职称证书、身份证明、劳动合同; （三）雷电防护装置检测质量管理手册； （四）仪器、设备及相关设施清单，以及检定或者校准证书； （五）安全生产管理制度。"},{"i":12,"n":"第十二条","txt":"符合本办法第七条和第八条相应条件的，可以申请雷电防护装置检测的甲级资质。申请单位除了提交本办法第十一条所规定的材料外，还应当提交以下材料： （一）《近三年已完成雷电防护装置检测项目表》(附表4)； （二）近三年二十个以上雷电防护装置检测项目的相关资料。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市气象主管机构应当在收到全部申请材料之日起五个工作日内，作出受理或者不予受理的书面决定。 申请材料齐全且符合法定形式的，应当受理，并出具加盖本行政机关专用印章和注明日期的书面凭证。对不予受理的，应当书面说明理由。 申请材料不齐全或者不符合法定形式的，气象主管机构应当当场或者在收到申请材料之日起五个工作日内一次告知申请单位需要补正的全部内容，逾期不告知的，自收到申请材料之日起即视为受理。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市气象主管机构受理后，可以根据工作需要指派两名以上工作人员到申请单位进行现场核查。"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市气象主管机构受理后，应当委托雷电防护装置检测资质评审委员会评审，并对评审结果进行审查。评审委员会评审时应当以记名投票方式进行表决，并提出评审意见。 省、自治区、直辖市气象主管机构应当建立雷电防护装置检测资质评审专家库，报国务院气象主管机构备案。 雷电防护装置检测资质评审委员会的委员应当从雷电防护装置检测资质评审专家库中随机抽取确定，并报国务院气象主管机构备案。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市气象主管机构应当自受理行政许可申请之日起二十个工作日内作出认定，专家评审所需时间不计入许可审查时限，但应当在作出受理决定时书面告知申请单位。 通过认定的，认定机构颁发《雷电防护装置检测资质证》，并在作出认定后三十个工作日内报国务院气象主管机构备案。 未通过认定的，认定机构在十个工作日内书面告知申请单位，并说明理由。"},{"i":17,"n":"第十七条","txt":"雷电防护装置检测单位及其人员从事雷电防护装置检测活动，应当遵守国家有关技术规范和标准。"},{"i":18,"n":"第十八条","txt":"雷电防护装置检测单位应当遵循客观、公平、公正、诚信原则，确保其出具的雷电防护装置检测数据、结果的真实、客观、准确，并对雷电防护装置检测数据、结果负责。"},{"i":19,"n":"第十九条","txt":"雷电防护装置检测单位不得与其检测项目的设计、施工、监理单位以及所使用的防雷产品生产、销售单位有隶属关系或者其他利害关系。"},{"i":20,"n":"第二十条","txt":"雷电防护装置检测资质管理实行年度报告制度。 雷电防护装置检测单位应当从取得资质证后次年起，在每年的第二季度向资质认定机构报送年度报告。年度报告应当包括持续符合资质认定条件和要求、执行技术标准和规范情况、分支机构设立和经营情况、检测项目表以及统计数据等内容。 资质认定机构对年度报告内容进行抽查，将抽查结果纳入信用管理，同时记入信用档案并公示。"},{"i":21,"n":"第二十一条","txt":"取得雷电防护装置检测资质的单位，应当在资质证有效期满三个月前，向原认定机构提出延续申请。原认定机构根据年度报告、信用档案及资质申请条件，在有效期满前作出是否准予延续的决定。逾期未提出延续申请的，资质证到期自动失效。"},{"i":22,"n":"第二十二条","txt":"取得雷电防护装置检测资质的单位在资质证有效期内名称、地址、法定代表人等发生变更的，应当在法人登记机关变更登记后三十个工作日内，向原资质认定机构申请办理资质证变更手续。 雷电防护装置检测资质的单位发生合并、分立以及注册地跨省、自治区、直辖市变更的，应当按照下列规定及时向所在地的省、自治区、直辖市气象主管机构申请核定资质。 （一）取得雷电防护装置检测资质的单位合并的，合并后存续或者新设立的单位可以承继合并前各方中较高等级的资质，但应当符合相应的资质条件； （二）取得雷电防护装置检测资质的单位分立的，分立后资质等级根据实际达到的资质条件重新核定； （三）取得雷电防护装置检测资质的单位跨省、自治区、直辖市变更注册地的，由新注册所在地的省、自治区、直辖市气象主管机构核定资质。"},{"i":23,"n":"第二十三条","txt":"雷电防护装置检测单位设立分支机构或者跨省、自治区、直辖市从事雷电防护装置检测活动的，应当及时向开展活动所在地的省、自治区、直辖市气象主管机构报告，并报送检测项目清单，接受监管。"},{"i":24,"n":"第二十四条","txt":"取得雷电防护装置检测资质的单位，应当按照资质等级承担相应的雷电防护装置检测工作。禁止无资质证或者超出资质等级承接雷电防护装置检测，禁止转包或者违法分包。 从事雷电防护装置检测活动的专业技术人员，不得同时在两个以上雷电防护装置检测资质单位兼职从业。"},{"i":25,"n":"第二十五条","txt":"任何单位不得以欺骗、弄虚作假等手段取得资质，不得伪造、涂改、出租、出借、挂靠、转让《雷电防护装置检测资质证》。"},{"i":26,"n":"第二十六条","txt":"省、自治区、直辖市气象主管机构应当组织或者委托第三方专业技术机构对雷电防护装置检测单位的检测质量进行考核。"},{"i":27,"n":"第二十七条","txt":"县级以上地方气象主管机构对本行政区域内的雷电防护装置检测活动进行监督检查，可以采取下列措施： （一）要求被检查的单位或者个人提供有关文件和资料，进行查询或者复制； （二）就有关事项询问被检查的单位或者个人，要求作出说明； （三）进入有关雷电防护装置检测现场进行监督检查。 气象主管机构进行监督检查时，有关单位和个人应当予以配合。"},{"i":28,"n":"第二十八条","txt":"取得雷电防护装置检测资质的单位不再符合相应资质条件的，由原资质认定的气象主管机构责令限期整改，整改期限最长不超过3个月。资质单位整改期间不得申请雷电防护装置检测资质的升级，不能承揽新的检测业务。 甲级雷电防护装置检测资质单位逾期不整改或者整改后仍达不到甲级资质条件的，可以申请重新核定资质等级；未申请重新核定资质等级的，予以撤销资质。乙级雷电防护装置检测资质单位逾期不整改或者整改后仍达不到乙级资质条件的，予以撤销资质。"},{"i":29,"n":"第二十九条","txt":"国务院气象主管机构应当建立全国雷电防护装置检测单位信用信息、资质等级情况公示制度。省、自治区、直辖市气象主管机构应当对在本行政区域内从事雷电防护装置检测活动单位的监督管理情况、信用信息等及时予以公布。 省、自治区、直辖市气象主管机构应当对本行政区域内取得雷电防护装置检测资质的单位建立信用管理制度，将雷电防护装置检测活动和监督管理等信息纳入信用档案，并作为资质延续、升级的依据。"},{"i":30,"n":"第三十条","txt":"雷电防护装置检测单位有下列情形之一的，县级以上气象主管机构视情节轻重，责令限期整改： （一）雷电防护装置检测标准适用错误的； （二）雷电防护装置检测方法不正确的； （三）雷电防护装置检测内容不全面、达不到相关技术要求或者不足以支持雷电防护装置检测结论的； （四）雷电防护装置检测结论不明确、不全面或错误的。"},{"i":31,"n":"第三十一条","txt":"鼓励防雷行业组织对雷电防护装置检测活动实行行业自律管理，并接受省、自治区、直辖市气象主管机构的政策、业务指导和行业监管。"},{"i":32,"n":"第三十二条","txt":"国家工作人员在雷电防护装置检测资质的认定和管理工作中玩忽职守、滥用职权、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"申请单位隐瞒有关情况、提供虚假材料申请资质认定的，有关气象主管机构不予受理或者不予行政许可，并给予警告。申请单位在一年内不得再次申请资质认定。"},{"i":34,"n":"第三十四条","txt":"被许可单位以欺骗、贿赂等不正当手段取得资质的，有关气象主管机构按照权限给予警告，撤销其资质证，可以并处三万元以下的罚款；被许可单位在三年内不得再次申请资质认定；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"雷电防护装置检测单位违反本办法规定，有下列行为之一的，由县级以上气象主管机构按照权限责令限期改正，拒不改正的给予警告，《雷电防护装置检测资质证》到期后不予延续，处罚结果纳入全国雷电防护装置检测单位信用信息系统并向社会公示： （一）与检测项目的设计、施工、监理单位以及所使用的防雷产品生产、销售单位有隶属关系或者其他利害关系的； （二）使用不符合条件的雷电防护装置检测人员的。"},{"i":36,"n":"第三十六条","txt":"雷电防护装置检测单位违反本办法规定，有下列行为之一的，按照《气象灾害防御条例》第四十五条的规定进行处罚： （一）伪造、涂改、出租、出借、挂靠、转让雷电防护装置检测资质证的； （二）向监督检查机构隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况的真实材料的； （三）转包或者违法分包雷电防护装置检测项目的； （四）无资质或者超越资质许可范围从事雷电防护装置检测的。"},{"i":37,"n":"第三十七条","txt":"电力、通信雷电防护装置检测资质管理办法由国务院气象主管机构和国务院电力或者国务院通信主管部门共同制定，另行公布。"},{"i":38,"n":"第三十八条","txt":"在本办法施行前，已取得各省、自治区、直辖市气象主管机构颁发的防雷装置检测资质的单位，应当在2017年9月30日前，按照本办法规定重新核定资质。"},{"i":39,"n":"第三十九条","txt":"各省、自治区、直辖市气象主管机构可以根据本办法制定实施细则，并报国务院气象主管机构备案。"},{"i":40,"n":"第四十条","txt":"本办法自2016年10月1日起施行。 附表： 1．雷电防护装置检测专业设备表 2．雷电防护装置检测资质申请表 3．专业技术人员简表 4．近三年已完成雷电防护装置检测项目表 （以上附表略，详情请登录中国气象局行政审批平台）"}],"leidianfanghuzhuangzhishejishenhehejungongyanshoug787d5a":[{"i":1,"n":"第一条","txt":"为了规范雷电防护装置设计审核和竣工验收工作，维护国家利益，保护人民生命财产和公共安全，依据《中华人民共和国气象法》《中华人民共和国行政许可法》和《气象灾害防御条例》等有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"县级以上地方气象主管机构负责本行政区域职责范围内雷电防护装置的设计审核和竣工验收工作。未设气象主管机构的县（市、区），由上一级气象主管机构负责雷电防护装置的设计审核和竣工验收工作。"},{"i":3,"n":"第三条","txt":"雷电防护装置的设计审核和竣工验收工作应当遵循公开、公平、公正以及便民、高效和信赖保护的原则。"},{"i":4,"n":"第四条","txt":"本规定适用于下列建设工程、场所和大型项目的雷电防护装置设计审核和竣工验收： （一）油库、气库、弹药库、化学品仓库和烟花爆竹、石化等易燃易爆建设工程和场所； （二）雷电易发区内的矿区、旅游景点或者投入使用的建（构）筑物、设施等需要单独安装雷电防护装置的场所； （三）雷电风险高且没有防雷标准规范、需要进行特殊论证的大型项目。"},{"i":5,"n":"第五条","txt":"雷电防护装置未经设计审核或者设计审核不合格的，不得施工。雷电防护装置未经竣工验收或者竣工验收不合格的，不得交付使用。"},{"i":6,"n":"第六条","txt":"雷电防护装置设计审核和竣工验收的程序、文书等应当依法予以公示。"},{"i":7,"n":"第七条","txt":"建设单位应当向当地气象主管机构提出雷电防护装置设计审核申请。 申请雷电防护装置设计审核应当提交以下材料： （一）《雷电防护装置设计审核申请表》（附表1）； （二）雷电防护装置设计说明书和设计图纸； （三）设计中所采用的防雷产品相关说明。"},{"i":8,"n":"第八条","txt":"气象主管机构应当在收到全部申请材料之日起五个工作日内，作出受理或者不予受理的书面决定。 申请材料齐全且符合法定形式的，应当受理，并出具《雷电防护装置设计审核受理回执》（附表2）。对不予受理的，应当书面说明理由。 申请材料不齐全或者不符合法定形式的，气象主管机构应当当场或者在收到申请材料之日起五个工作日内一次告知申请单位需要补正的全部内容，并出具《雷电防护装置设计审核资料补正通知》（附表3）。逾期不告知的，自收到申请材料之日起即视为受理。"},{"i":9,"n":"第九条","txt":"气象主管机构受理后，应当委托有关机构开展雷电防护装置设计技术评价。 有关机构开展雷电防护装置设计技术评价应当遵守国家有关标准、规范和规程，出具雷电防护装置设计技术评价报告，并对评价报告负责。 雷电防护装置设计技术评价报告结论应当包含雷电防护装置设计文件是否符合国家有关标准和国务院气象主管机构规定的使用要求。"},{"i":10,"n":"第十条","txt":"雷电防护装置设计审核内容： （一）申请材料的合法性； （二）雷电防护装置设计技术评价报告。"},{"i":11,"n":"第十一条","txt":"气象主管机构应当在受理之日起十个工作日内完成审核工作。 雷电防护装置设计文件经审核符合要求的，气象主管机构应当颁发《雷电防护装置设计核准意见书》（附表4）。施工单位应当按照经核准的设计图纸进行施工。在施工中需要变更和修改雷电防护装置设计的，应当按照原程序重新申请设计审核。 雷电防护装置设计经审核不符合要求的，气象主管机构出具《不予许可决定书》（附表5）。"},{"i":12,"n":"第十二条","txt":"雷电防护装置实行竣工验收制度。建设单位应当向气象主管机构提出申请，并提交以下材料： （一）《雷电防护装置竣工验收申请表》（附表6）； （二）雷电防护装置竣工图纸等技术资料； （三）防雷产品出厂合格证和安装记录。"},{"i":13,"n":"第十三条","txt":"气象主管机构应当在收到全部申请材料之日起五个工作日内，作出受理或者不予受理的书面决定。 申请材料齐全且符合法定形式的，应当受理，并出具《雷电防护装置竣工验收受理回执》（附表7）。对不予受理的，应当书面说明理由。 申请材料不齐全或者不符合法定形式的，气象主管机构应当当场或者在收到申请材料之日起五个工作日内一次告知申请单位需要补正的全部内容，并出具《雷电防护装置竣工验收资料补正通知》（附表8）。逾期不告知的，自收到申请材料之日起即视为受理。"},{"i":14,"n":"第十四条","txt":"气象主管机构受理后，应当委托取得雷电防护装置检测资质的单位开展雷电防护装置检测。 取得雷电防护装置检测资质的单位开展检测应当遵守国家有关标准、规范和规程，出具雷电防护装置检测报告并对检测报告负责。出具的雷电防护装置检测报告必须全面、真实、可靠。 雷电防护装置检测报告结论应当包含安装的雷电防护装置是否按照核准的施工图施工完成；是否符合国家有关标准和国务院气象主管机构规定的使用要求。"},{"i":15,"n":"第十五条","txt":"雷电防护装置竣工验收内容： （一）申请材料的合法性； （二）雷电防护装置检测报告。"},{"i":16,"n":"第十六条","txt":"气象主管机构应当在受理之日起十个工作日内作出竣工验收结论。 雷电防护装置经验收符合要求的，气象主管机构应当出具《雷电防护装置验收意见书》（附表9）。 雷电防护装置验收不符合要求的，气象主管机构应当出具《不予验收决定书》（附表10）。"},{"i":17,"n":"第十七条","txt":"申请单位不得以欺骗、贿赂等手段提出申请或者通过许可；不得涂改、伪造雷电防护装置设计审核和竣工验收有关材料或者文件。"},{"i":18,"n":"第十八条","txt":"县级以上地方气象主管机构应当加强对雷电防护装置设计审核和竣工验收的监督与检查，建立健全监督制度，履行监督责任。"},{"i":19,"n":"第十九条","txt":"上级气象主管机构应当加强对下级气象主管机构雷电防护装置设计审核和竣工验收工作的监督检查，及时纠正违规行为。"},{"i":20,"n":"第二十条","txt":"县级以上地方气象主管机构进行雷电防护装置设计审核和竣工验收的监督检查时，不得妨碍正常的生产经营活动，不得索取或者收受任何财物，不得谋取其他利益。"},{"i":21,"n":"第二十一条","txt":"单位或者个人发现违法从事雷电防护装置设计审核和竣工验收活动时，有权向县级以上地方气象主管机构举报，县级以上地方气象主管机构应当及时核实、处理。"},{"i":22,"n":"第二十二条","txt":"县级以上地方气象主管机构履行监督检查职责时，有权采取下列措施： （一）要求被检查的单位或者个人提供雷电防护装置设计图纸等文件和资料，进行查询或者复制； （二）要求被检查的单位或者个人就有关雷电防护装置的设计、安装、检测、验收和投入使用的情况作出说明； （三）进入有关建（构）筑物和场所进行检查。"},{"i":23,"n":"第二十三条","txt":"县级以上地方气象主管机构进行雷电防护装置设计审核和竣工验收监督检查时，有关单位和个人应当予以支持和配合，并提供工作方便，不得拒绝与阻碍依法执行公务。"},{"i":24,"n":"第二十四条","txt":"申请单位隐瞒有关情况、提供虚假材料申请设计审核或者竣工验收许可的，有关气象主管机构不予受理或者不予行政许可，并给予警告。"},{"i":25,"n":"第二十五条","txt":"申请单位以欺骗、贿赂等不正当手段通过设计审核或者竣工验收的，有关气象主管机构按照权限给予警告，撤销其许可证书，可以并处三万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"违反本规定，有下列行为之一的，按照《气象灾害防御条例》第四十五条规定进行处罚： （一）在雷电防护装置设计、施工中弄虚作假的； （二）雷电防护装置未经设计审核或者设计审核不合格施工的，未经竣工验收或者竣工验收不合格交付使用的。"},{"i":27,"n":"第二十七条","txt":"县级以上地方气象主管机构在监督检查工作中发现违法行为构成犯罪的，应当移送有关机关，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"国家工作人员在雷电防护装置设计审核和竣工验收工作中由于滥用职权、玩忽职守，导致重大雷电灾害事故的，由所在单位依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"违反本规定，导致雷击造成火灾、爆炸、人员伤亡以及国家或者他人财产重大损失的，由主管部门给予直接责任人处分；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"各省、自治区、直辖市气象主管机构可以根据本规定制定实施细则，并报国务院气象主管机构备案。"},{"i":31,"n":"第三十一条","txt":"本规定自2021年1月1日起施行。2011年7月22日公布的中国气象局第21号令《防雷装置设计审核和竣工验收规定》同时废止。 附表： 1．雷电防护装置设计审核申请表 2．雷电防护装置设计审核受理回执 3．雷电防护装置设计审核资料补正通知 4．雷电防护装置设计核准意见书 5．雷电防护装置设计审核不予许可决定书 6．雷电防护装置竣工验收申请表 7．雷电防护装置竣工验收受理回执 8．雷电防护装置竣工验收资料补正通知 9．雷电防护装置验收意见书 10．雷电防护装置不予验收决定书 （以上附表略，详情请登录中国气象局行政审批网上平台）"}]};
